import { formatCompact, formatNumber, isNum } from '@/lib/ink/charts/chart-scale'
import { xScaleFor, yScaleFor, type DomainEnd } from '@/lib/ink/charts/chart-data'
import { lttb } from '@/lib/ink/charts/chart-scale'
import {
  DASHES,
  MARKERS,
  PATTERNS,
  type Dash,
  type MarkerShape,
  type NotePen,
  type Pattern,
  type XYKind,
  type XYBand,
  type XYNote,
  type XYRef,
  type XYSeries,
  type XYSpec,
} from '@/lib/ink/charts/chart-types'

export type Row = Record<string, unknown>

export function toNum(v: unknown): number | null {
  if (isNum(v)) return v
  if (typeof v === 'string' && v.trim() !== '') {
    const n = Number(v)
    return Number.isFinite(n) ? n : null
  }
  return null
}

export interface SeriesInput {
  key: string
  name?: string
  kind?: XYKind
  slot?: number
  pattern?: Pattern | 'auto'
  marker?: MarkerShape | 'auto'
  dash?: Dash | 'auto'
}

export interface NoteInput {
  at: 'max' | 'min' | 'first' | 'last' | number | string
  series?: string | number
  text: string
  pen?: NotePen
  shape?: 'loop' | 'underline' | 'none'
  dx?: number
  dy?: number
}

export interface BandInput {
  from: string | number
  to: string | number
  text?: string
}

export interface RefInput {
  y?: number
  x?: number
  label?: string
  pen?: NotePen
}

export interface XYBuildInput {
  rows: readonly Row[]
  xKey: string
  series: readonly SeriesInput[]
  kind: XYKind
  stacked?: boolean
  horizontal?: boolean
  curve?: 'smooth' | 'linear' | 'step'
  domain?: readonly [DomainEnd, DomainEnd]
  xDomain?: readonly [DomainEnd, DomainEnd]
  zero?: boolean
  tickCount?: number
  yFormat?: (v: number) => string
  xFormat?: (v: unknown, index: number) => string
  valueFormat?: (v: number) => string
  dots?: 'auto' | boolean
  values?: 'auto' | boolean
  grid?: boolean
  showX?: boolean
  showY?: boolean
  notes?: readonly NoteInput[]
  refs?: readonly RefInput[]
  bands?: readonly BandInput[]
  patterns?: boolean | 'auto'
  hidden?: ReadonlySet<string> | readonly string[]
  state?: 'ready' | 'empty' | 'loading'
  stateText?: string
  sizeKey?: string
}

const hiddenSet = (h: XYBuildInput['hidden']): ReadonlySet<string> => (h instanceof Set ? h : new Set(h ?? []))

export const MAX_BARS = 240
export const MAX_BARS_TOTAL = 480
export const MAX_POINTS = 1500

export function capRows(rows: readonly Row[], keys: readonly string[], kind: XYKind, xKey: string): { rows: readonly Row[]; total?: number } {
  const n = rows.length
  if (kind === 'scatter') return { rows }
  const limit = Math.min(MAX_BARS, Math.max(48, Math.floor(MAX_BARS_TOTAL / Math.max(1, keys.length))))
  if (kind === 'bar' && n > limit) {
    const size = Math.ceil(n / limit)
    const out: Row[] = []
    for (let i = 0; i < n; i += size) {
      const chunk = rows.slice(i, i + size)
      const row: Row = { [xKey]: chunk[0][xKey] }
      for (const k of keys) {
        const vs = chunk.map((r) => toNum(r[k])).filter(isNum)
        row[k] = vs.length ? vs.reduce((a, b) => a + b, 0) / vs.length : null
      }
      out.push(row)
    }
    return { rows: out, total: n }
  }
  if (kind !== 'bar' && n > MAX_POINTS) {
    const first = keys[0]
    const pts = rows.map((r, i) => [i, toNum(first ? r[first] : 0) ?? 0] as [number, number])
    return { rows: lttb(pts, MAX_POINTS).map((i) => rows[i]), total: n }
  }
  return { rows }
}

export function autoLook(kind: XYKind, slot: number, drawn: number, patterns: boolean | 'auto'): { pattern: Pattern; marker: MarkerShape; dash: Dash } {
  const pat = PATTERNS[((slot % PATTERNS.length) + PATTERNS.length) % PATTERNS.length]
  const shifted = PATTERNS[(((slot + 1) % PATTERNS.length) + PATTERNS.length) % PATTERNS.length]
  const many = drawn > 1 || patterns === true
  if (patterns === false) return { pattern: 'solid', marker: 'circle', dash: 'solid' }
  return {
    pattern: kind === 'area' ? shifted : kind === 'bar' ? (many ? pat : 'solid') : 'solid',
    marker: many ? MARKERS[((slot % MARKERS.length) + MARKERS.length) % MARKERS.length] : 'circle',
    dash: many ? DASHES[((slot % DASHES.length) + DASHES.length) % DASHES.length] : 'solid',
  }
}

export function seriesLook(kind: XYKind, slot: number, count: number, patterns: boolean | 'auto', own: { pattern?: Pattern | 'auto'; marker?: MarkerShape | 'auto'; dash?: Dash | 'auto' } = {}): { pattern: Pattern; marker: MarkerShape; dash: Dash } {
  const auto = autoLook(kind, slot, count, patterns)
  if (patterns === false) return auto
  return {
    pattern: own.pattern && own.pattern !== 'auto' ? own.pattern : auto.pattern,
    marker: own.marker && own.marker !== 'auto' ? own.marker : auto.marker,
    dash: own.dash && own.dash !== 'auto' ? own.dash : auto.dash,
  }
}

export function buildXY(i: XYBuildInput): XYSpec {
  return buildXYRows(i).spec
}

export function buildXYRows(i: XYBuildInput): { spec: XYSpec; rows: readonly Row[] } {
  const hidden = hiddenSet(i.hidden)
  const scatter = i.kind === 'scatter'
  const capped = capRows(i.rows, i.series.map((s) => s.key), i.kind, i.xKey)
  i = { ...i, rows: capped.rows }
  const drawn = i.series.map((s, idx) => ({ s, idx })).filter((e) => !hidden.has(e.s.key))
  const patterns = i.patterns ?? 'auto'
  const n = scatter ? 0 : i.rows.length
  const series: XYSeries[] = drawn.map(({ s, idx }) => {
    const kind = s.kind ?? i.kind
    const slot = s.slot ?? idx
    const look = seriesLook(kind, slot, i.series.length, patterns, s)
    const values = i.rows.map((r) => toNum(r[s.key]))
    const out: XYSeries = {
      key: s.key,
      name: s.name ?? s.key,
      slot,
      kind,
      pattern: look.pattern,
      marker: look.marker,
      dash: look.dash,
      values,
    }
    if (scatter) {
      out.xs = i.rows.map((r) => toNum(r[i.xKey]) ?? Number.NaN)
      if (i.sizeKey) out.sizes = i.rows.map((r) => toNum(r[i.sizeKey as string]) ?? Number.NaN)
    }
    return out
  })

  const valueFormat = i.valueFormat ?? formatNumber
  const yFormat = i.yFormat ?? formatCompact
  const refs: XYRef[] = (i.refs ?? []).flatMap((r): XYRef[] => (isNum(r.y) ? [{ value: r.y, axis: 'y', label: r.label, pen: r.pen ?? 'red' }] : isNum(r.x) ? [{ value: r.x, axis: 'x', label: r.label, pen: r.pen ?? 'red' }] : []))
  const hasFill = series.some((s) => s.kind === 'bar' || s.kind === 'area')
  const y = yScaleFor(series, {
    n,
    stacked: !!i.stacked,
    zero: i.zero ?? hasFill,
    domain: i.domain,
    ticks: i.tickCount ?? 5,
    format: yFormat,
    include: refs.filter((r) => r.axis === 'y').map((r) => r.value),
  })
  const cats = scatter ? [] : i.rows.map((r, idx) => (i.xFormat ? i.xFormat(r[i.xKey], idx) : String(r[i.xKey] ?? '')))
  let x: { xMin?: number; xMax?: number; xTicks?: XYSpec['xTicks']; xTicksAlt?: XYSpec['xTicksAlt'] } = {}
  if (scatter) {
    const xs = series.flatMap((s) => s.xs ?? []).filter(isNum)
    x = xScaleFor(xs, { domain: i.xDomain, ticks: 6, format: i.xFormat ? (v) => i.xFormat!(v, 0) : formatCompact, include: refs.filter((r) => r.axis === 'x').map((r) => r.value) })
  }

  const notes: XYNote[] = []
  for (const nt of i.notes ?? []) {
    const si = nt.series === undefined ? 0 : typeof nt.series === 'number' ? nt.series : series.findIndex((s) => s.key === nt.series)
    const ser = series[si]
    if (!ser) continue
    let idx = -1
    if (typeof nt.at === 'number') idx = nt.at
    else if (nt.at === 'first') idx = ser.values.findIndex(isNum)
    else if (nt.at === 'last') idx = ser.values.length - 1 - [...ser.values].reverse().findIndex(isNum)
    else if (nt.at === 'max' || nt.at === 'min') {
      let best = -1
      ser.values.forEach((v, k) => {
        if (isNum(v) && (best < 0 || (nt.at === 'max' ? v > (ser.values[best] as number) : v < (ser.values[best] as number)))) best = k
      })
      idx = best
    } else idx = cats.indexOf(nt.at)
    if (idx < 0 || idx >= ser.values.length || !isNum(ser.values[idx])) continue
    notes.push({ s: si, i: idx, text: nt.text, pen: nt.pen ?? 'red', shape: nt.shape ?? 'loop', dx: nt.dx, dy: nt.dy })
  }

  const bands: XYBand[] = []
  for (const b of i.bands ?? []) {
    const at = (v: string | number) => (typeof v === 'number' ? v : cats.indexOf(v))
    const a = at(b.from)
    const z = at(b.to)
    if (a < 0 || z < 0 || a >= cats.length || z >= cats.length || scatter) continue
    bands.push({ i0: Math.min(a, z), i1: Math.max(a, z), text: b.text })
  }

  const valueLabels = i.values === false ? undefined : series.map((s) => s.values.map((v) => (s.kind === 'bar' && isNum(v) ? valueFormat(v) : null)))
  const state = i.state ?? (series.length === 0 || (!scatter && n === 0) || series.every((s) => s.values.every((v) => !isNum(v))) ? 'empty' : 'ready')

  const spec: XYSpec = {
    type: 'xy',
    cats,
    series,
    stacked: !!i.stacked,
    horizontal: !!i.horizontal,
    curve: i.curve ?? 'smooth',
    yMin: y.yMin,
    yMax: y.yMax,
    yTicks: y.yTicks,
    ...(y.yTicksAlt.length ? { yTicksAlt: y.yTicksAlt } : {}),
    ...x,
    dots: i.dots ?? 'auto',
    values: i.values ?? 'auto',
    valueLabels,
    grid: i.grid ?? true,
    showX: i.showX ?? true,
    showY: i.showY ?? true,
    zero: i.zero ?? hasFill,
    notes,
    refs,
    bands,
    patterns: patterns !== false,
    state,
    stateText: i.stateText,
    ...(capped.total ? { total: capped.total } : {}),
  }
  return { spec, rows: i.rows }
}

import { coarserTicks, formatCompact, formatNumber, isNum, niceScale, round, ticksIn } from '@/lib/ink/charts/chart-scale'
import { stackRanges } from '@/lib/ink/charts/chart-xy'
import type { AxisTick, XYSeries, XYSpec } from '@/lib/ink/charts/chart-types'

export type DomainEnd = number | 'auto' | undefined

export interface ScaleOpts {
  n: number
  stacked: boolean
  zero: boolean
  domain?: readonly [DomainEnd, DomainEnd]
  ticks?: number
  format?: (v: number) => string
  include?: readonly number[]
}

export function yScaleFor(series: readonly XYSeries[], o: ScaleOpts): { yMin: number; yMax: number; yTicks: AxisTick[]; yTicksAlt: AxisTick[][] } {
  const fmt = o.format ?? formatCompact
  let lo = Infinity
  let hi = -Infinity
  const take = (v: number) => {
    if (v < lo) lo = v
    if (v > hi) hi = v
  }
  const stackable = (k: 'bar' | 'area') => series.filter((s) => s.kind === k)
  for (const k of ['bar', 'area'] as const) {
    const group = stackable(k)
    if (!group.length) continue
    for (const row of stackRanges(group as XYSeries[], o.stacked, o.n)) for (const r of row) if (r) (take(r[0]), take(r[1]))
    take(0)
  }
  for (const s of series) if (s.kind === 'line' || s.kind === 'scatter') for (const v of s.values) if (isNum(v)) take(v)
  for (const v of o.include ?? []) if (isNum(v)) take(v)
  if (!Number.isFinite(lo) || !Number.isFinite(hi)) {
    lo = 0
    hi = 1
  }
  if (o.zero) {
    lo = Math.min(lo, 0)
    hi = Math.max(hi, 0)
  } else if (hi > lo) {
    const pad = (hi - lo) * 0.06
    lo -= pad
    hi += pad
  }
  const [dLo, dHi] = o.domain ?? [undefined, undefined]
  const pinLo = typeof dLo === 'number' ? dLo : undefined
  const pinHi = typeof dHi === 'number' ? dHi : undefined
  const sc = niceScale(pinLo ?? lo, pinHi ?? hi, o.ticks ?? 5)
  const yMin = pinLo ?? sc.min
  const yMax = pinHi ?? sc.max
  const values = pinLo !== undefined || pinHi !== undefined ? ticksIn(yMin, yMax, o.ticks ?? 5) : sc.ticks
  const label = (v: number): AxisTick => ({ v, label: fmt(v) })
  return { yMin, yMax, yTicks: values.map(label), yTicksAlt: coarserTicks(yMin, yMax, values).map((t) => t.map(label)) }
}

export function xScaleFor(values: readonly number[], o: { domain?: readonly [DomainEnd, DomainEnd]; ticks?: number; format?: (v: number) => string; include?: readonly number[] } = {}): { xMin: number; xMax: number; xTicks: AxisTick[]; xTicksAlt: AxisTick[][] } {
  const fmt = o.format ?? formatCompact
  const all = [...values.filter(isNum), ...(o.include ?? [])]
  const lo = all.length ? Math.min(...all) : 0
  const hi = all.length ? Math.max(...all) : 1
  const [dLo, dHi] = o.domain ?? [undefined, undefined]
  const pinLo = typeof dLo === 'number' ? dLo : undefined
  const pinHi = typeof dHi === 'number' ? dHi : undefined
  const sc = niceScale(pinLo ?? lo, pinHi ?? hi, o.ticks ?? 6)
  const xMin = pinLo ?? sc.min
  const xMax = pinHi ?? sc.max
  const vals = pinLo !== undefined || pinHi !== undefined ? ticksIn(xMin, xMax, o.ticks ?? 6) : sc.ticks
  const label = (v: number): AxisTick => ({ v, label: fmt(v) })
  return { xMin, xMax, xTicks: vals.map(label), xTicksAlt: coarserTicks(xMin, xMax, vals).map((t) => t.map(label)) }
}

export interface SummaryOpts {
  kind: string
  title?: string
  format?: (v: number) => string
}

const list = (items: string[]): string => (items.length <= 2 ? items.join(' and ') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`)

export function summarizeXY(spec: XYSpec, o: SummaryOpts): string {
  const fmt = o.format ?? formatNumber
  const named = o.title ? `${o.title}. ` : ''
  if (spec.state === 'loading') return `${named}${o.kind}. Loading.`
  const scatter = spec.series.some((s) => s.kind === 'scatter')
  const count = scatter ? spec.series.reduce((n, s) => n + s.values.filter(isNum).length, 0) : spec.cats.length
  if (!spec.series.length || !count || spec.state === 'empty') return `${named}${o.kind}. No data.`
  const unit = scatter ? `${count} point${count === 1 ? '' : 's'}` : `${count} categor${count === 1 ? 'y' : 'ies'}${count > 1 ? ` from ${spec.cats[0]} to ${spec.cats[spec.cats.length - 1]}` : ` (${spec.cats[0]})`}`
  const parts = spec.series.map((s) => {
    const nums = s.values.map((v, i) => [v, i] as const).filter((e): e is readonly [number, number] => isNum(e[0]))
    if (!nums.length) return `${s.name}: no values`
    const lo = nums.reduce((a, b) => (b[0] < a[0] ? b : a))
    const hi = nums.reduce((a, b) => (b[0] > a[0] ? b : a))
    const at = (e: readonly [number, number]) => (scatter ? '' : ` in ${spec.cats[e[1]]}`)
    return nums.length === 1 ? `${s.name}: ${fmt(nums[0][0])}` : `${s.name}: from ${fmt(lo[0])}${at(lo)} to ${fmt(hi[0])}${at(hi)}`
  })
  const many = spec.series.length
  const extra = (spec.stacked ? ' Stacked.' : spec.horizontal ? ' Horizontal bars.' : '') + (spec.total ? ` Thinned from ${formatNumber(spec.total)} rows to keep the drawing readable.` : '')
  const marked = spec.bands.length ? ` Marked: ${spec.bands.map((b) => `${b.text ? `${b.text}, ` : ''}${spec.cats[b.i0]}${b.i1 !== b.i0 ? ` to ${spec.cats[b.i1]}` : ''}`).join('; ')}.` : ''
  return `${named}${o.kind} with ${many} series (${list(spec.series.map((s) => s.name))}) and ${unit}.${extra} ${parts.join('. ')}.${marked}`.replace(/\.\./g, '.')
}

export interface TableModel {
  head: string[]
  rows: string[][]
  clipped?: { shown: number; total: number }
}

export const TABLE_ROW_CAP = 240

export function tableXY(spec: XYSpec, o: { format?: (v: number) => string; xHead?: string; xFormat?: (v: number) => string } = {}): TableModel {
  const fmt = o.format ?? formatNumber
  const scatter = spec.series.some((s) => s.kind === 'scatter')
  if (scatter) {
    const rows: string[][] = []
    spec.series.forEach((s) => {
      s.values.forEach((v, j) => {
        const x = s.xs?.[j]
        if (isNum(v) && isNum(x)) rows.push([s.name, (o.xFormat ?? fmt)(x), fmt(v)])
      })
    })
    const total = rows.length
    return { head: ['Series', o.xHead ?? 'x', 'y'], rows: rows.slice(0, TABLE_ROW_CAP), clipped: total > TABLE_ROW_CAP ? { shown: TABLE_ROW_CAP, total } : undefined }
  }
  const total = spec.cats.length
  const rows = spec.cats.slice(0, TABLE_ROW_CAP).map((c, i) => [c, ...spec.series.map((s) => (isNum(s.values[i]) ? fmt(s.values[i] as number) : ''))])
  return { head: [o.xHead ?? '', ...spec.series.map((s) => s.name)], rows, clipped: total > TABLE_ROW_CAP ? { shown: TABLE_ROW_CAP, total } : undefined }
}

export function announceRow(label: string, entries: ReadonlyArray<{ name: string; value: string }>): string {
  return `${label}: ${entries.map((e) => `${e.name} ${e.value}`).join(', ')}`
}

export { round }

import { isNum } from '@/lib/ink/charts/chart-scale'

const DAY = 86_400_000
export const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'] as const
export const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'] as const
export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as const

export function dayMs(d: unknown): number {
  if (d instanceof Date) return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())
  if (typeof d === 'string') {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d)
    if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3])
  }
  return Number.NaN
}

export function isoDay(ms: number): string {
  const d = new Date(ms)
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`
}

export function formatDay(ms: number, year = false): string {
  const d = new Date(ms)
  return `${WEEKDAYS[d.getUTCDay()]}, ${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}${year ? `, ${d.getUTCFullYear()}` : ''}`
}

export function levelOf(v: number | null, max: number, levels: number, thresholds?: readonly number[]): number {
  if (!isNum(v) || v <= 0) return 0
  if (thresholds?.length) {
    let lv = 0
    for (const t of thresholds) if (v >= t) lv++
    return Math.min(levels - 1, Math.max(1, lv))
  }
  return Math.min(levels - 1, Math.max(1, Math.ceil((v / (max || 1)) * (levels - 1))))
}

export interface HeatCells {
  cols: number
  rows: number
  levels: number[]
  values: Array<number | null>
  days: number[]
  colLabels: Array<{ i: number; text: string }>
  rowLabels: Array<{ i: number; text: string }>
  max: number
}

export interface CalendarInput {
  date: unknown
  value: unknown
}

export interface CalendarOpts {
  weeks?: number
  end?: unknown
  weekStart?: 0 | 1
  levels: number
  thresholds?: readonly number[]
  weekdayLabels?: boolean
  monthLabels?: boolean
}

export function buildCalendar(rows: readonly CalendarInput[], o: CalendarOpts): HeatCells {
  const byDay = new Map<number, number>()
  let last = Number.NEGATIVE_INFINITY
  let first = Number.POSITIVE_INFINITY
  for (const r of rows) {
    const ms = dayMs(r.date)
    const v = typeof r.value === 'number' ? r.value : Number(r.value)
    if (!Number.isFinite(ms) || !Number.isFinite(v)) continue
    byDay.set(ms, (byDay.get(ms) ?? 0) + v)
    last = Math.max(last, ms)
    first = Math.min(first, ms)
  }
  const ws = o.weekStart ?? 0
  const endMs = Number.isFinite(dayMs(o.end)) ? dayMs(o.end) : Number.isFinite(last) ? last : dayMs('2026-01-01')
  const startFromData = Number.isFinite(first) ? first : endMs
  const weekOf = (ms: number) => Math.floor((ms - dayMs('1970-01-04') - ws * DAY) / (7 * DAY))
  const spanWeeks = weekOf(endMs) - weekOf(startFromData) + 1
  const weeks = Math.max(1, Math.min(o.weeks ?? Math.min(53, spanWeeks), 60))
  const lastWeek = weekOf(endMs)
  const week0 = lastWeek - weeks + 1
  const gridStart = dayMs('1970-01-04') + ws * DAY + week0 * 7 * DAY
  let max = 0
  for (const [ms, v] of byDay) if (ms >= gridStart && ms <= endMs) max = Math.max(max, v)
  const levels: number[] = []
  const values: Array<number | null> = []
  const days: number[] = []
  for (let r = 0; r < 7; r++) {
    for (let c = 0; c < weeks; c++) {
      const ms = gridStart + (c * 7 + r) * DAY
      if (ms > endMs) {
        levels.push(-1)
        values.push(null)
        days.push(Number.NaN)
        continue
      }
      const v = byDay.get(ms) ?? 0
      levels.push(levelOf(v, max, o.levels, o.thresholds))
      values.push(v)
      days.push(ms)
    }
  }
  const colLabels: Array<{ i: number; text: string }> = []
  if (o.monthLabels !== false) {
    let prev = -1
    let prevCol = -99
    for (let c = 0; c < weeks; c++) {
      const ms = gridStart + c * 7 * DAY
      const month = new Date(ms).getUTCMonth()
      const startsHere = c === 0 || new Date(ms - 7 * DAY).getUTCMonth() !== month
      if (startsHere && month !== prev && c > 0 && c < 3 && colLabels.length === 1 && colLabels[0].i === 0) {
        colLabels.length = 0
        prevCol = -99
      }
      if (startsHere && month !== prev && c - prevCol >= 3) {
        colLabels.push({ i: c, text: MONTHS[month] })
        prev = month
        prevCol = c
      }
    }
  }
  const rowLabels: Array<{ i: number; text: string }> = []
  if (o.weekdayLabels !== false) for (const wd of [1, 3, 5]) rowLabels.push({ i: (wd - ws + 7) % 7, text: WEEKDAYS[wd] })
  return { cols: weeks, rows: 7, levels, values, days, colLabels, rowLabels, max }
}

export interface GridInput {
  row: unknown
  col: unknown
  value: unknown
}

export function buildGrid(data: readonly GridInput[], o: { rows?: readonly string[]; cols?: readonly string[]; levels: number; thresholds?: readonly number[] }): HeatCells {
  const rowNames = (o.rows ? [...o.rows] : [...new Set(data.map((d) => String(d.row)))]).slice(0, 200)
  const colNames = (o.cols ? [...o.cols] : [...new Set(data.map((d) => String(d.col)))]).slice(0, 200)
  const cell = new Map<string, number>()
  let max = 0
  for (const d of data) {
    const v = typeof d.value === 'number' ? d.value : Number(d.value)
    if (!Number.isFinite(v)) continue
    const key = `${String(d.row)}\u0000${String(d.col)}`
    cell.set(key, (cell.get(key) ?? 0) + v)
  }
  for (const v of cell.values()) max = Math.max(max, v)
  const levels: number[] = []
  const values: Array<number | null> = []
  rowNames.forEach((r) =>
    colNames.forEach((c) => {
      const v = cell.get(`${r}\u0000${c}`)
      levels.push(v === undefined ? 0 : levelOf(v, max, o.levels, o.thresholds))
      values.push(v ?? 0)
    }),
  )
  return {
    cols: colNames.length,
    rows: rowNames.length,
    levels,
    values,
    days: levels.map(() => Number.NaN),
    colLabels: colNames.map((text, i) => ({ i, text })),
    rowLabels: rowNames.map((text, i) => ({ i, text })),
    max,
  }
}

import { layoutGauge, layoutPie, layoutRadar, layoutRadial, TAU } from '@/lib/ink/charts/chart-polar'
import { layoutHeat, layoutSpark, layoutTally } from '@/lib/ink/charts/chart-mini'
import { layoutXY } from '@/lib/ink/charts/chart-xy'
import type { ChartLayoutBase, ChartTargets, GaugeSpec, HeatSpec, PieSpec, RadarSpec, RadialSpec, SparkSpec, TallySpec, XYSpec } from '@/lib/ink/charts/chart-types'

export type ChartSpec = XYSpec | PieSpec | RadarSpec | RadialSpec | GaugeSpec | SparkSpec | TallySpec | HeatSpec

export function layoutChart(spec: ChartSpec, box: { w: number; h: number }, calm = false): ChartLayoutBase {
  switch (spec.type) {
    case 'xy':
      return layoutXY(spec, box, calm)
    case 'pie':
      return layoutPie(spec, box, calm)
    case 'radar':
      return layoutRadar(spec, box, calm)
    case 'radial':
      return layoutRadial(spec, box, calm)
    case 'gauge':
      return layoutGauge(spec, box, calm)
    case 'spark':
      return layoutSpark(spec, box)
    case 'tally':
      return layoutTally(spec, box, calm)
    case 'heat':
      return layoutHeat(spec, box, calm)
  }
}

const norm = (a: number): number => ((a % TAU) + TAU) % TAU

export function hitIndex(t: ChartTargets, x: number, y: number): number | null {
  if (t.n <= 0) return null
  switch (t.mode) {
    case 'x':
    case 'y': {
      const pos = t.pos ?? []
      const v = t.mode === 'x' ? x : y
      let best = -1
      let bd = Infinity
      for (let i = 0; i < pos.length; i++) {
        const d = Math.abs(pos[i] - v)
        if (d < bd) {
          bd = d
          best = i
        }
      }
      return best < 0 ? null : best
    }
    case 'point': {
      let best = -1
      let bd = 40 * 40
      for (let i = 0; i < t.n; i++) {
        const d = (t.cx[i] - x) ** 2 + (t.cy[i] - y) ** 2
        if (d < bd) {
          bd = d
          best = i
        }
      }
      return best < 0 ? null : best
    }
    case 'sector': {
      const s = t.sector
      if (!s) return null
      const r = Math.hypot(x - s.cx, y - s.cy)
      const ang = Math.atan2(x - s.cx, s.cy - y)
      for (let i = 0; i < t.n; i++) {
        if (r < s.r0[i] || r > s.r1[i]) continue
        const span = s.a1[i] - s.a0[i]
        if (norm(ang - s.a0[i]) <= span + 1e-9) return i
      }
      return null
    }
    case 'cell': {
      const c = t.cells
      if (!c) return null
      const col = Math.floor((x - c.x0) / c.cw)
      const row = Math.floor((y - c.y0) / c.ch)
      if (col < 0 || row < 0 || col >= c.cols || row >= c.rows) return null
      const k = row * c.cols + col
      return c.index[k] >= 0 ? k : null
    }
  }
}

const clampI = (v: number, n: number): number => Math.max(0, Math.min(n - 1, v))

export function stepIndex(t: ChartTargets, from: number | null, key: string): number | null {
  const n = t.n
  if (n <= 0) return null
  const cur = from == null || from < 0 || from >= n ? null : from
  if (key === 'Home') return t.mode === 'cell' ? firstCell(t) : 0
  if (key === 'End') return t.mode === 'cell' ? lastCell(t) : n - 1
  if (t.mode === 'cell' && t.cells) {
    const c = t.cells
    const d = key === 'ArrowRight' ? [1, 0] : key === 'ArrowLeft' ? [-1, 0] : key === 'ArrowDown' ? [0, 1] : key === 'ArrowUp' ? [0, -1] : key === 'PageDown' ? [7, 0] : key === 'PageUp' ? [-7, 0] : null
    if (!d) return null
    if (cur == null) return firstCell(t)
    let col = cur % c.cols
    let row = Math.floor(cur / c.cols)
    for (let guard = 0; guard < c.cols + c.rows; guard++) {
      col += d[0]
      row += d[1]
      if (col < 0 || row < 0 || col >= c.cols || row >= c.rows) return cur
      const k = row * c.cols + col
      if (c.index[k] >= 0) return k
    }
    return cur
  }
  const forward = t.mode === 'y' ? key === 'ArrowDown' : t.mode === 'sector' ? key === 'ArrowRight' || key === 'ArrowDown' : key === 'ArrowRight'
  const backward = t.mode === 'y' ? key === 'ArrowUp' : t.mode === 'sector' ? key === 'ArrowLeft' || key === 'ArrowUp' : key === 'ArrowLeft'
  if (!forward && !backward) return null
  if (cur == null) return forward ? 0 : n - 1
  if (t.mode === 'sector') return (cur + (forward ? 1 : -1) + n) % n
  return clampI(cur + (forward ? 1 : -1), n)
}

function firstCell(t: ChartTargets): number {
  const i = t.cells?.index.findIndex((k) => k >= 0) ?? 0
  return i < 0 ? 0 : i
}
function lastCell(t: ChartTargets): number {
  const idx = t.cells?.index ?? []
  for (let i = idx.length - 1; i >= 0; i--) if (idx[i] >= 0) return i
  return 0
}

import type { Pt } from '@/lib/ink/types'
import { bucketOf, clampN, isNum, monotoneCurve, textWidth, type LabelFont } from '@/lib/ink/charts/chart-scale'
import type { ChartLabel, ChartLayoutBase, ChartTargets, CursorSpec, HeatSpec, SparkSpec, TallySpec } from '@/lib/ink/charts/chart-types'

export interface SparkLayout extends ChartLayoutBase {
  pts: Array<Pt | null>
  segs: Pt[][]
  bars: Array<{ x: number; y: number; w: number; h: number }>
  baseY: number
  last: Pt | null
  minPt: Pt | null
  maxPt: Pt | null
}

export function layoutSpark(spec: SparkSpec, box: { w: number; h: number }): SparkLayout {
  const { w, h } = box
  const n = spec.values.length
  const padX = spec.variant === 'bar' ? 1.5 : 4
  const padY = 5
  const x0 = padX
  const x1 = w - padX - (spec.ends && spec.variant !== 'bar' ? 3 : 0)
  const y0 = padY
  const y1 = h - padY
  const span = spec.max - spec.min || 1
  const yOf = (v: number) => clampN(y1 - ((v - spec.min) / span) * (y1 - y0), y0 - 4, y1 + 4)
  const slot = n > 0 ? (x1 - x0) / n : 0
  const xOf = (i: number) => (spec.variant === 'bar' ? x0 + slot * (i + 0.5) : n < 2 ? (x0 + x1) / 2 : x0 + ((x1 - x0) * i) / (n - 1))
  const pts: Array<Pt | null> = spec.values.map((v, i) => (isNum(v) ? [xOf(i), yOf(v)] : null))
  const runs: Pt[][] = []
  let cur: Pt[] = []
  for (const p of pts) {
    if (p) cur.push(p)
    else if (cur.length) (runs.push(cur), (cur = []))
  }
  if (cur.length) runs.push(cur)
  const segs = runs.map((r) => (r.length > 2 ? monotoneCurve(r, 3) : r))
  const bw = clampN(slot * 0.62, 1.6, 14)
  const bars = spec.variant === 'bar' ? pts.flatMap((p) => (p ? [{ x: p[0] - bw / 2, y: p[1], w: bw, h: Math.max(1.2, y1 - p[1]) }] : [])) : []
  const real = pts.filter((p): p is Pt => !!p)
  const last = real.length ? real[real.length - 1] : null
  let minPt: Pt | null = null
  let maxPt: Pt | null = null
  real.forEach((p) => {
    if (!minPt || p[1] > minPt[1]) minPt = p
    if (!maxPt || p[1] < maxPt[1]) maxPt = p
  })
  const targets: ChartTargets = { n, mode: 'x', pos: pts.map((p, i) => (p ? p[0] : xOf(i))), cx: pts.map((p, i) => (p ? p[0] : xOf(i))), cy: pts.map((p) => (p ? p[1] : y1)), nav: 'linear' }
  const cursorAt = (i: number): CursorSpec[] => {
    const p = pts[i]
    return p ? [{ kind: 'ring', x: p[0] - 7, y: p[1] - 7, w: 14, h: 14, slot: spec.slot }] : []
  }
  return { w, h, bucket: bucketOf(w), labels: [], targets, cursorAt, pts, segs, bars, baseY: y1, last, minPt, maxPt }
}

export interface TallyRowGeom {
  index: number
  y: number
  gh: number
  x: number
  marks: number
  right: number
}
export interface TallyLayout extends ChartLayoutBase {
  rows: TallyRowGeom[]
  unit: number
  markArea: { x0: number; x1: number }
}

export const MAX_MARKS = 250
const TALLY_UNITS = [1, 2, 5, 10, 20, 25, 50, 100, 200, 250, 500, 1000, 2000, 5000, 10000, 100000]

export function layoutTally(spec: TallySpec, box: { w: number; h: number }, calm = false): TallyLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const font: LabelFont = calm ? 'hand' : 'script'
  const tick = calm ? 13 : bucket === 'sm' ? 15 : 17
  const labels: ChartLabel[] = []
  const m = spec.rows.length
  const nameW = Math.min(w * 0.34, Math.max(0, ...spec.rows.map((r) => textWidth(r.name, tick, font))) + 4)
  const totalW = Math.max(0, ...spec.totals.map((t) => textWidth(t, tick, font))) + 6
  const x0 = nameW + 14
  const x1 = w - totalW - 10
  const rh = m ? clampN((h - 8) / m, 24, 52) : 40
  const gh = clampN(rh * 0.62, 14, 28)
  const maxCount = Math.max(1, ...spec.rows.map((r) => (Number.isFinite(r.count) ? r.count : 0)))
  const groupW = (g: number) => 1.05 * g + 6
  const fits = (unit: number) => Math.ceil(maxCount / unit / 5) * groupW(gh) - 6 <= x1 - x0
  const need = Math.ceil(maxCount / MAX_MARKS)
  const floor = TALLY_UNITS.find((u) => u >= need) ?? need
  const unit = Math.max(floor, spec.unit > 0 ? spec.unit : (TALLY_UNITS.find(fits) ?? TALLY_UNITS[TALLY_UNITS.length - 1]))
  const usedH = m * rh
  const top = Math.max(4, Math.min(12, (h - usedH) / 2))
  const rows: TallyRowGeom[] = spec.rows.map((r, i) => {
    const marks = Math.ceil((Number.isFinite(r.count) ? r.count : 0) / unit)
    const groups = Math.ceil(marks / 5)
    const y = top + i * rh + (rh - gh) / 2
    const right = x0 + Math.max(0, groups * groupW(gh) - 6 - (marks % 5 && marks % 5 !== 0 ? (5 - (marks % 5)) * 0.26 * gh : 0))
    labels.push({ id: `n-${i}`, text: r.name, x: 4, y: y + gh / 2, anchor: 'start', valign: 'middle', role: 'cat', size: tick, tone: 'ink', maxW: nameW })
    labels.push({ id: `t-${i}`, text: spec.totals[i] ?? String(r.count), x: w - 4, y: y + gh / 2, anchor: 'end', valign: 'middle', role: 'value', size: tick, tone: 'muted' })
    return { index: i, y, gh, x: x0, marks, right }
  })
  if (unit > 1 && spec.state === 'ready') {
    labels.push({ id: 'unit', text: `each mark = ${unit}`, x: w - 4, y: h - 2, anchor: 'end', valign: 'bottom', role: 'sub', size: Math.max(12, tick - 3), tone: 'muted' })
  }
  if (spec.state !== 'ready' || !m) labels.push({ id: 'state', text: spec.stateText ?? (spec.state === 'loading' ? 'Loading' : 'No data'), x: w / 2, y: h / 2, anchor: 'middle', valign: 'middle', role: 'center', size: 20, tone: 'muted' })
  const targets: ChartTargets = { n: m, mode: 'y', pos: rows.map((r) => r.y + r.gh / 2), cx: rows.map((r) => (r.right + x0) / 2), cy: rows.map((r) => r.y + r.gh / 2), nav: 'linear' }
  const cursorAt = (i: number): CursorSpec[] => {
    const r = rows[i]
    return r ? [{ kind: 'column', x: 0, y: r.y - (rh - r.gh) / 2, w, h: rh }] : []
  }
  return { w, h, bucket, labels, targets, cursorAt, rows, unit, markArea: { x0, x1 } }
}

export interface HeatCell {
  col: number
  row: number
  x: number
  y: number
  level: number
}
export interface HeatLayout extends ChartLayoutBase {
  cs: number
  cell: number
  gx: number
  gy: number
  cells: HeatCell[]
  legend: { x: number; y: number; cell: number } | null
}

export function layoutHeat(spec: HeatSpec, box: { w: number; h: number }, calm = false): HeatLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const font: LabelFont = calm ? 'hand' : 'script'
  const tick = calm ? 12 : bucket === 'sm' ? 13 : 14.5
  const labels: ChartLabel[] = []
  const left = spec.rowLabels.length ? Math.max(...spec.rowLabels.map((r) => textWidth(r.text, tick, font))) + 10 : 4
  const top = spec.colLabels.length ? tick + 8 : 4
  const bottom = spec.legend ? tick + 16 : 4
  const availW = w - left - 4
  const availH = h - top - bottom
  const cs = Math.max(4, Math.min(availW / Math.max(1, spec.cols), availH / Math.max(1, spec.rows), 34))
  const gap = clampN(cs * 0.16, 1.4, 4.5)
  const cell = cs - gap
  const gx = left
  const gy = top + Math.max(0, (availH - cs * spec.rows) / 2)
  const cells: HeatCell[] = []
  const index: number[] = []
  spec.levels.forEach((lv, k) => {
    const col = k % spec.cols
    const row = Math.floor(k / spec.cols)
    if (lv >= 0) cells.push({ col, row, x: gx + col * cs, y: gy + row * cs, level: lv })
    index.push(lv >= 0 ? k : -1)
  })
  if (spec.state === 'ready') {
    if (spec.variant === 'grid') {
      for (const c of spec.colLabels) labels.push({ id: `c-${c.i}`, text: c.text, x: gx + c.i * cs + cs / 2, y: gy - 6, anchor: 'middle', valign: 'bottom', role: 'x', size: tick, tone: 'ink', maxW: Math.max(cs, 24) })
    } else {
      let free = Number.NEGATIVE_INFINITY
      for (const c of spec.colLabels) {
        const x = gx + c.i * cs
        if (x < free) continue
        labels.push({ id: `c-${c.i}`, text: c.text, x, y: gy - 6, anchor: 'start', valign: 'bottom', role: 'x', size: tick, tone: 'ink' })
        free = x + textWidth(c.text, tick, font) + 6
      }
    }
    let lastY = Number.NEGATIVE_INFINITY
    for (const r of spec.rowLabels) {
      const y = gy + r.i * cs + cs / 2
      if (y - lastY < tick * 0.95) continue
      labels.push({ id: `r-${r.i}`, text: r.text, x: gx - 6, y, anchor: 'end', valign: 'middle', role: 'y', size: tick, tone: 'muted' })
      lastY = y
    }
  }
  let legend: HeatLayout['legend'] = null
  if (spec.legend && spec.state === 'ready') {
    const lc = clampN(cs * 0.9, 10, 16)
    const lw = spec.levelCount * (lc + 3)
    const ly = gy + cs * spec.rows + 8 + lc / 2
    const lx = Math.min(gx + cs * spec.cols, w - 4) - lw - textWidth(spec.legend.more, tick, font) - 8
    legend = { x: lx, y: ly - lc / 2, cell: lc }
    labels.push({ id: 'less', text: spec.legend.less, x: lx - 6, y: ly, anchor: 'end', valign: 'middle', role: 'sub', size: tick, tone: 'muted' })
    labels.push({ id: 'more', text: spec.legend.more, x: lx + lw + 6, y: ly, anchor: 'start', valign: 'middle', role: 'sub', size: tick, tone: 'muted' })
  }
  if (spec.state !== 'ready') labels.push({ id: 'state', text: spec.stateText ?? (spec.state === 'loading' ? 'Loading' : 'No data'), x: w / 2, y: h / 2, anchor: 'middle', valign: 'middle', role: 'center', size: 20, tone: 'muted' })
  const total = spec.cols * spec.rows
  const targets: ChartTargets = {
    n: total,
    mode: 'cell',
    cx: Array.from({ length: total }, (_, k) => gx + (k % spec.cols) * cs + cs / 2),
    cy: Array.from({ length: total }, (_, k) => gy + Math.floor(k / spec.cols) * cs),
    nav: 'grid',
    cols: spec.cols,
    cells: { x0: gx, y0: gy, cw: cs, ch: cs, cols: spec.cols, rows: spec.rows, index },
  }
  const cursorAt = (i: number): CursorSpec[] => {
    if (i < 0 || i >= total || index[i] < 0) return []
    return [{ kind: 'cell', x: gx + (i % spec.cols) * cs - 2, y: gy + Math.floor(i / spec.cols) * cs - 2, w: cell + 4 + gap, h: cell + 4 + gap }]
  }
  return { w, h, bucket, labels, targets, cursorAt, cs, cell, gx, gy, cells, legend }
}

import type { Pt } from '@/lib/ink/types'
import { bucketOf, clampN, isNum, shares, textWidth, type LabelFont } from '@/lib/ink/charts/chart-scale'
import type { ChartLabel, ChartLayoutBase, ChartTargets, CursorSpec, GaugeSpec, Pattern, PieSpec, RadarSpec, RadialSpec } from '@/lib/ink/charts/chart-types'

export const TAU = Math.PI * 2
export const deg = (d: number): number => (d * Math.PI) / 180

export const polar = (cx: number, cy: number, r: number, a: number): Pt => [cx + r * Math.sin(a), cy - r * Math.cos(a)]

export function angleOf(cx: number, cy: number, x: number, y: number): number {
  const a = Math.atan2(x - cx, cy - y)
  return a < 0 ? a + TAU : a
}

export function arcPts(cx: number, cy: number, r: number, a0: number, a1: number, step = 4): Pt[] {
  const n = Math.max(2, Math.ceil((Math.abs(a1 - a0) * r) / step))
  const out: Pt[] = []
  for (let i = 0; i <= n; i++) out.push(polar(cx, cy, r, a0 + ((a1 - a0) * i) / n))
  return out
}

export function sectorPoly(cx: number, cy: number, r0: number, r1: number, a0: number, a1: number, step = 4): Pt[] {
  const outer = arcPts(cx, cy, r1, a0, a1, step)
  if (r0 <= 0.5) return [[cx, cy], ...outer]
  return [...outer, ...arcPts(cx, cy, r0, a1, a0, step)]
}

function boundsOf(pts: Pt[], pad: number): { x: number; y: number; w: number; h: number } {
  let x0 = Infinity
  let y0 = Infinity
  let x1 = -Infinity
  let y1 = -Infinity
  for (const p of pts) {
    x0 = Math.min(x0, p[0])
    y0 = Math.min(y0, p[1])
    x1 = Math.max(x1, p[0])
    y1 = Math.max(y1, p[1])
  }
  return { x: x0 - pad, y: y0 - pad, w: x1 - x0 + 2 * pad, h: y1 - y0 + 2 * pad }
}

interface PolarMetrics {
  font: LabelFont
  tick: number
  value: number
  center: number
}
const metrics = (bucket: 'sm' | 'md' | 'lg', calm: boolean): PolarMetrics =>
  calm ? { font: 'hand', tick: 12.5, value: 12.5, center: bucket === 'sm' ? 22 : 28 } : { font: 'script', tick: bucket === 'sm' ? 14 : 15, value: 15, center: bucket === 'sm' ? 30 : 40 }

export interface PieSector {
  index: number
  a0: number
  a1: number
  fraction: number
}
export interface PieLayout extends ChartLayoutBase {
  cx: number
  cy: number
  R: number
  r0: number
  sectors: PieSector[]
  sliceOf: number[]
  total: number
}

export function layoutPie(spec: PieSpec, box: { w: number; h: number }, calm = false): PieLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const M = metrics(bucket, calm)
  const labels: ChartLabel[] = []
  const total = spec.slices.reduce((n, s) => n + (isNum(s.value) && s.value > 0 ? s.value : 0), 0)
  const wantsLabels = spec.labels && spec.state === 'ready' && total > 0
  const pad = wantsLabels ? M.tick + 20 : 8
  const R = Math.max(12, Math.min(w, h) / 2 - pad)
  const cx = w / 2
  const cy = h / 2
  const r0 = R * clampN(spec.inner, 0, 0.9)
  const sectors: PieSector[] = []
  const sliceOf: number[] = []
  let a = deg(spec.start)
  spec.slices.forEach((s, i) => {
    const v = isNum(s.value) && s.value > 0 ? s.value : 0
    if (!v || !total) return
    const f = v / total
    sectors.push({ index: i, a0: a, a1: a + f * TAU, fraction: f })
    sliceOf.push(i)
    a += f * TAU
  })
  if (wantsLabels) {
    const pct = shares(spec.slices.map((s) => s.value))
    for (const sc of sectors) {
      if (sc.fraction < 0.045) continue
      const mid = (sc.a0 + sc.a1) / 2
      const p = polar(cx, cy, R + 12, mid)
      const text = spec.slices[sc.index].label ?? pct[sc.index]
      const s = Math.sin(mid)
      labels.push({ id: `l-${sc.index}`, text, x: p[0], y: p[1], anchor: s > 0.25 ? 'start' : s < -0.25 ? 'end' : 'middle', valign: Math.cos(mid) > 0.3 ? 'bottom' : Math.cos(mid) < -0.3 ? 'top' : 'middle', role: 'value', size: M.value, tone: 'ink' })
    }
  }
  const targets: ChartTargets = {
    n: sectors.length,
    mode: 'sector',
    cx: sectors.map((s) => polar(cx, cy, (R + r0) / 2, (s.a0 + s.a1) / 2)[0]),
    cy: sectors.map((s) => polar(cx, cy, (R + r0) / 2, (s.a0 + s.a1) / 2)[1]),
    nav: 'linear',
    sector: { cx, cy, r0: sectors.map(() => r0), r1: sectors.map(() => R + 4), a0: sectors.map((s) => s.a0), a1: sectors.map((s) => s.a1) },
  }
  const cursorAt = (i: number): CursorSpec[] => {
    const s = sectors[i]
    if (!s) return []
    const b = boundsOf(sectorPoly(cx, cy, r0, R + 3, s.a0, s.a1, 6), 8)
    return [{ kind: 'slice', ...b, cx: cx - b.x, cy: cy - b.y, r0, r1: R + 3, a0: s.a0, a1: s.a1 }]
  }
  if (spec.state !== 'ready' || !total) {
    labels.push({ id: 'state', text: spec.stateText ?? (spec.state === 'loading' ? 'Loading' : 'No data'), x: cx, y: cy, anchor: 'middle', valign: 'middle', role: 'center', size: M.center * 0.6, tone: 'muted' })
  }
  return { w, h, bucket, labels, targets, cursorAt, cx, cy, R, r0, sectors, sliceOf, total }
}

export interface RadarLayout extends ChartLayoutBase {
  cx: number
  cy: number
  R: number
  axesAngles: number[]
  rings: number[]
  polys: Array<Array<Pt | null>>
}

export function layoutRadar(spec: RadarSpec, box: { w: number; h: number }, calm = false): RadarLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const M = metrics(bucket, calm)
  const n = spec.axes.length
  const labels: ChartLabel[] = []
  const widest = Math.max(0, ...spec.axes.map((t) => textWidth(t, M.tick, M.font)))
  const sidePad = Math.min(widest, w * 0.22) + 16
  const R = Math.max(14, Math.min((w - 2 * sidePad) / 2, (h - 2 * (M.tick + 12)) / 2))
  const cx = w / 2
  const cy = h / 2
  const axesAngles = spec.axes.map((_, k) => (k * TAU) / Math.max(1, n))
  const levelCount = Math.min(12, Math.max(1, Math.round(spec.levels) || 1))
  const rings = Array.from({ length: levelCount }, (_, l) => (R * (l + 1)) / levelCount)
  const polys = spec.series.map((s) =>
    spec.axes.map((_, k) => {
      const v = s.values[k]
      return isNum(v) ? polar(cx, cy, R * clampN(v / (spec.max || 1), 0, 1.02), axesAngles[k]) : null
    }),
  )
  if (spec.state === 'ready' && n >= 3) {
    axesAngles.forEach((a, k) => {
      const p = polar(cx, cy, R + 10, a)
      const s = Math.sin(a)
      const c = Math.cos(a)
      labels.push({ id: `a-${k}`, text: spec.axes[k], x: p[0], y: p[1], anchor: s > 0.3 ? 'start' : s < -0.3 ? 'end' : 'middle', valign: c > 0.5 ? 'bottom' : c < -0.5 ? 'top' : 'middle', role: 'cat', size: M.tick, tone: 'ink', maxW: sidePad })
    })
    const gapAngle = Math.PI / n
    spec.ringLabels.forEach((t, l) => {
      if (!t || bucket === 'sm') return
      const r = rings[levelCount - 1 - l] ?? 0
      const p = polar(cx, cy, r, gapAngle)
      labels.push({ id: `r-${l}`, text: t, x: p[0] + 2, y: p[1], anchor: 'start', valign: 'middle', role: 'y', size: Math.max(12, M.tick - 2), tone: 'muted' })
    })
  }
  const targets: ChartTargets = {
    n,
    mode: 'sector',
    cx: axesAngles.map((a) => polar(cx, cy, R, a)[0]),
    cy: axesAngles.map((a) => polar(cx, cy, R, a)[1]),
    nav: 'linear',
    sector: { cx, cy, r0: axesAngles.map(() => 0), r1: axesAngles.map(() => R + 30), a0: axesAngles.map((a) => a - Math.PI / Math.max(1, n)), a1: axesAngles.map((a) => a + Math.PI / Math.max(1, n)) },
  }
  const cursorAt = (i: number): CursorSpec[] => {
    if (i < 0 || i >= n) return []
    const tip = polar(cx, cy, R, axesAngles[i])
    const b = boundsOf([[cx, cy], tip], 10)
    return [{ kind: 'spoke', ...b, x1: cx - b.x, y1: cy - b.y, x2: tip[0] - b.x, y2: tip[1] - b.y }]
  }
  if (spec.state !== 'ready' || n < 3) labels.push({ id: 'state', text: spec.stateText ?? (spec.state === 'loading' ? 'Loading' : 'No data'), x: cx, y: cy, anchor: 'middle', valign: 'middle', role: 'center', size: M.center * 0.6, tone: 'muted' })
  return { w, h, bucket, labels, targets, cursorAt, cx, cy, R, axesAngles, rings, polys }
}

export interface RadialArc {
  index: number
  r: number
  t: number
  a0: number
  a1: number
  aEnd: number
}
export interface RadialLayout extends ChartLayoutBase {
  cx: number
  cy: number
  R: number
  hole: number
  arcs: RadialArc[]
}

export function layoutRadial(spec: RadialSpec, box: { w: number; h: number }, calm = false): RadialLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const M = metrics(bucket, calm)
  const labels: ChartLabel[] = []
  const cx = w / 2
  const cy = h / 2
  const R = Math.max(20, Math.min(w, h) / 2 - 8)
  const m = Math.max(1, spec.rings.length)
  const hole = R * (m > 4 ? 0.22 : 0.3)
  const band = (R - hole) / m
  const t = clampN(band * 0.7, 6, 28)
  const a0 = deg(spec.start)
  const aEnd = deg(spec.end)
  const arcs: RadialArc[] = spec.rings.map((ring, k) => {
    const f = clampN(isNum(ring.value) ? ring.value / (ring.max || 1) : 0, 0, 1)
    return { index: k, r: R - band * (k + 0.5), t, a0, a1: a0 + (aEnd - a0) * f, aEnd }
  })
  if (spec.state === 'ready' && Math.abs(spec.end - spec.start) < 330 && bucket !== 'sm') {
    const left = spec.start === 0
    arcs.forEach((a, k) => labels.push({ id: `n-${k}`, text: spec.rings[k].name, x: cx + (left ? -6 : 6), y: cy - a.r, anchor: left ? 'end' : 'start', valign: 'middle', role: 'cat', size: Math.max(12, M.tick - 1), tone: 'ink', maxW: cx - 10 }))
  }
  const targets: ChartTargets = {
    n: spec.rings.length,
    mode: 'sector',
    cx: arcs.map((a) => polar(cx, cy, a.r, (a.a0 + a.a1) / 2)[0]),
    cy: arcs.map((a) => polar(cx, cy, a.r, (a.a0 + a.a1) / 2)[1]),
    nav: 'linear',
    sector: { cx, cy, r0: arcs.map((a) => a.r - band / 2), r1: arcs.map((a) => a.r + band / 2), a0: arcs.map((a) => a.a0), a1: arcs.map((a) => a.aEnd) },
  }
  const cursorAt = (i: number): CursorSpec[] => {
    const a = arcs[i]
    if (!a) return []
    const b = boundsOf(sectorPoly(cx, cy, a.r - a.t / 2 - 2, a.r + a.t / 2 + 2, a.a0, a.aEnd, 6), 6)
    return [{ kind: 'slice', ...b, cx: cx - b.x, cy: cy - b.y, r0: a.r - a.t / 2 - 2, r1: a.r + a.t / 2 + 2, a0: a.a0, a1: a.aEnd }]
  }
  if (spec.state !== 'ready' || !spec.rings.length) labels.push({ id: 'state', text: spec.stateText ?? (spec.state === 'loading' ? 'Loading' : 'No data'), x: cx, y: cy, anchor: 'middle', valign: 'middle', role: 'center', size: M.center * 0.6, tone: 'muted' })
  return { w, h, bucket, labels, targets, cursorAt, cx, cy, R, hole, arcs }
}

export interface GaugeZoneGeom {
  a0: number
  a1: number
  slot: number
  pattern: Pattern
}
export interface GaugeLayout extends ChartLayoutBase {
  cx: number
  cy: number
  R: number
  t: number
  a0: number
  a1: number
  av: number
  zones: GaugeZoneGeom[]
  tickAngles: number[]
}

export function layoutGauge(spec: GaugeSpec, box: { w: number; h: number }, calm = false): GaugeLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const M = metrics(bucket, calm)
  const labels: ChartLabel[] = []
  const half = deg(spec.sweep) / 2
  const below = M.center + 6
  const down = Math.max(0, -Math.cos(half))
  const R = Math.max(20, Math.min(w / 2 - 14, (h - 16 - below * (spec.sweep <= 180 ? 1 : 0.6)) / (1 + down)))
  const used = R * (1 + down) + below * (spec.sweep <= 180 ? 1 : 0.6)
  const cx = w / 2
  const cy = Math.max(R + 6, (h - used) / 2 + R)
  const t = clampN(R * 0.2, 9, 30)
  const span = Math.max(1e-6, spec.max - spec.min)
  const f = clampN((spec.value - spec.min) / span, 0, 1)
  const a0 = -half
  const a1 = half
  const av = a0 + (a1 - a0) * f
  const zones: GaugeZoneGeom[] = []
  let prev = spec.min
  for (const z of spec.zones) {
    const to = clampN(z.to, spec.min, spec.max)
    if (to > prev) zones.push({ a0: a0 + ((prev - spec.min) / span) * (a1 - a0), a1: a0 + ((to - spec.min) / span) * (a1 - a0), slot: z.slot, pattern: z.pattern })
    prev = to
  }
  const tickCount = Math.min(60, Math.max(0, Math.round(spec.ticks) || 0))
  const tickAngles = Array.from({ length: tickCount + 1 }, (_, k) => a0 + ((a1 - a0) * k) / Math.max(1, tickCount))
  if (spec.state === 'ready') {
    const pa = polar(cx, cy, R - t / 2, a0)
    const pb = polar(cx, cy, R - t / 2, a1)
    labels.push({ id: 'min', text: spec.minLabel, x: pa[0], y: pa[1] + t / 2 + 6, anchor: 'middle', valign: 'top', role: 'x', size: M.tick, tone: 'muted' })
    labels.push({ id: 'max', text: spec.maxLabel, x: pb[0], y: pb[1] + t / 2 + 6, anchor: 'middle', valign: 'top', role: 'x', size: M.tick, tone: 'muted' })
  } else labels.push({ id: 'state', text: spec.stateText ?? (spec.state === 'loading' ? 'Loading' : 'No data'), x: cx, y: cy - R * 0.35, anchor: 'middle', valign: 'middle', role: 'center', size: M.center * 0.6, tone: 'muted' })
  const targets: ChartTargets = { n: 0, mode: 'point', cx: [], cy: [], nav: 'linear' }
  return { w, h, bucket, labels, targets, cursorAt: () => [], cx, cy, R, t, a0, a1, av, zones, tickAngles }
}

import type { Pt } from '@/lib/ink/types'

export type Bucket = 'sm' | 'md' | 'lg'

export function bucketOf(w: number): Bucket {
  return w < 280 ? 'sm' : w < 560 ? 'md' : 'lg'
}

export const clampN = (v: number, a: number, b: number): number => (v < a ? a : v > b ? b : v)

export const round = (v: number, d = 2): number => {
  const k = 10 ** d
  const r = Math.round(v * k) / k
  return r === 0 ? 0 : r
}

export const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)

function niceNum(range: number, roundIt: boolean): number {
  const exp = Math.floor(Math.log10(range))
  const f = range / 10 ** exp
  let nf: number
  if (roundIt) nf = f < 1.5 ? 1 : f < 3 ? 2 : f < 7 ? 5 : 10
  else nf = f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10
  return nf * 10 ** exp
}

export interface NiceScale {
  min: number
  max: number
  step: number
  ticks: number[]
}

export function niceScale(min: number, max: number, count = 5): NiceScale {
  let lo = Math.min(min, max)
  let hi = Math.max(min, max)
  if (!Number.isFinite(lo) || !Number.isFinite(hi)) {
    lo = 0
    hi = 1
  }
  if (lo === hi) {
    const pad = Math.abs(lo) > 0 ? Math.abs(lo) * 0.5 : 1
    lo -= lo === 0 ? 0 : pad * 0.5
    hi += pad
    if (lo > 0 && min >= 0) lo = 0
  }
  const step = niceNum(niceNum(hi - lo, false) / Math.max(1, count - 1), true)
  const nmin = Math.floor(lo / step + 1e-9) * step
  const nmax = Math.ceil(hi / step - 1e-9) * step
  const ticks: number[] = []
  for (let v = nmin, i = 0; v <= nmax + step * 0.5 && i < 60; v += step, i++) ticks.push(round(v, 10))
  return { min: round(nmin, 10), max: round(nmax, 10), step, ticks }
}

export function ticksIn(min: number, max: number, count = 5): number[] {
  if (!(max > min)) return [min]
  const step = niceNum((max - min) / Math.max(1, count - 1), true)
  const out: number[] = []
  for (let v = Math.ceil(min / step - 1e-9) * step, i = 0; v <= max + step * 1e-6 && i < 60; v += step, i++) out.push(round(v, 10))
  return out
}

export function coarserTicks(min: number, max: number, dense: readonly number[]): number[][] {
  const seen = new Set<string>([dense.join(',')])
  const out: number[][] = []
  for (const count of [4, 3, 2]) {
    const t = ticksIn(min, max, count)
    const key = t.join(',')
    if (t.length < 2 || seen.has(key)) continue
    seen.add(key)
    out.push(t)
  }
  return out
}

export function shares(values: readonly number[], decimals = 0): string[] {
  const k = 10 ** decimals
  const pos = values.map((v) => (isNum(v) && v > 0 ? v : 0))
  const total = pos.reduce((n, v) => n + v, 0)
  if (!total) return values.map(() => '0%')
  const raw = pos.map((v) => (v / total) * 100 * k)
  const floor = raw.map(Math.floor)
  let left = Math.round(100 * k) - floor.reduce((n, v) => n + v, 0)
  const order = raw.map((r, i) => [r - floor[i], i] as const).sort((a, b) => b[0] - a[0] || a[1] - b[1])
  for (const [, i] of order) {
    if (left <= 0) break
    if (pos[i] > 0) {
      floor[i]++
      left--
    }
  }
  return floor.map((f) => `${round(f / k, decimals)}%`)
}

export function radarRim(top: number, levels = 4): number {
  const lv = Math.max(1, Math.round(levels) || 1)
  if (!isNum(top) || top <= 0) return lv
  const per = top / lv
  const exp = Math.floor(Math.log10(per))
  const f = per / 10 ** exp
  const nice = [1, 1.5, 2, 2.5, 3, 4, 5, 6, 7.5, 10].find((s) => s >= f - 1e-9) ?? 10
  return round(nice * 10 ** exp * lv, 6)
}

const SUFFIX: Array<[number, string]> = [
  [1e12, 'T'],
  [1e9, 'B'],
  [1e6, 'M'],
  [1e3, 'k'],
]

export function formatNumber(v: number, maxDecimals = 2): string {
  if (!Number.isFinite(v)) return ''
  const neg = v < 0
  const s = round(Math.abs(v), maxDecimals).toString()
  const [int, dec] = s.split('.')
  const grouped = int.replace(/\B(?=(\d{3})+(?!\d))/g, ',')
  return (neg ? '-' : '') + grouped + (dec ? '.' + dec : '')
}

export function formatCompact(v: number): string {
  if (!Number.isFinite(v)) return ''
  const a = Math.abs(v)
  for (const [k, s] of SUFFIX) {
    if (a >= k) {
      const x = round(a / k, a / k >= 100 ? 0 : 1)
      return (v < 0 ? '-' : '') + x + s
    }
  }
  return (v < 0 ? '-' : '') + round(a, a < 1 ? 2 : a < 10 ? 1 : 0)
}

export function formatPercent(fraction: number, decimals = 0): string {
  return `${round(fraction * 100, decimals)}%`
}

export type LabelFont = 'script' | 'hand' | 'mono'
const EM: Record<LabelFont, number> = { script: 0.4, hand: 0.47, mono: 0.6 }

export function textWidth(s: string, size: number, font: LabelFont = 'script'): number {
  const base = EM[font]
  let em = 0
  for (const ch of s) {
    if (ch === ' ') em += base * 0.55
    else if ('il.,:;!\'|'.includes(ch)) em += base * 0.6
    else if ('mwMW%@'.includes(ch)) em += base * 1.45
    else if (ch >= 'A' && ch <= 'Z') em += base * 1.12
    else em += base
  }
  return em * size
}

export const LABEL_SLACK = 1.15
export const LABEL_GAP = 8

export function labelWidth(s: string, size: number, font: LabelFont = 'script'): number {
  return textWidth(s, size, font) * LABEL_SLACK
}

export function pickLabelIndices(widths: readonly number[], pitch: number, gap = LABEL_GAP): { idx: number[]; stride: number } {
  const n = widths.length
  if (n === 0) return { idx: [], stride: 1 }
  const last = n - 1
  const clear = (a: number, b: number): boolean => (b - a) * pitch - (widths[a] + widths[b]) / 2 >= gap
  const run = (s: number): number[] => {
    const out: number[] = []
    for (let i = 0; i < n; i += s) out.push(i)
    return out
  }
  const valid = (p: readonly number[]): boolean => p.every((v, k) => k === 0 || clear(p[k - 1], v))
  let s = 1
  while (s < n && !valid(run(s))) s++
  const upTo = (k: number) => Math.min(last, Math.ceil(s * k))
  const tries: Array<[number, boolean]> = [[1.5, false], [1.34, true], [2, true]]
  for (const [k, tail] of tries) {
    for (let t = s; t <= upTo(k); t++) {
      const p = run(t)
      if (!valid(p)) continue
      const rem = last % t
      if (rem === 0) return { idx: p, stride: t }
      if (tail && 2 * rem > t && clear(p[p.length - 1], last)) return { idx: [...p, last], stride: t }
    }
  }
  const p = run(s)
  if (p[p.length - 1] !== last && clear(p[p.length - 1], last)) p.push(last)
  return { idx: p, stride: s }
}

export function clearLabels<T extends { x: number; w: number }>(items: readonly T[], gap = LABEL_GAP): T[] {
  const out: T[] = []
  const clear = (a: T, b: T): boolean => b.x - a.x - (a.w + b.w) / 2 >= gap
  items.forEach((it, k) => {
    if (!out.length || clear(out[out.length - 1], it)) return void out.push(it)
    if (k !== items.length - 1) return
    while (out.length > 1 && !clear(out[out.length - 1], it)) out.pop()
    if (clear(out[out.length - 1], it)) out.push(it)
  })
  return out
}

export function monotoneCurve(pts: Pt[], step = 4): Pt[] {
  const n = pts.length
  if (n < 3) return pts.map((p) => [p[0], p[1]] as Pt)
  const dx: number[] = []
  const m: number[] = []
  for (let i = 0; i < n - 1; i++) {
    dx.push(pts[i + 1][0] - pts[i][0] || 1e-6)
    m.push((pts[i + 1][1] - pts[i][1]) / dx[i])
  }
  const t: number[] = new Array(n)
  t[0] = m[0]
  t[n - 1] = m[n - 2]
  for (let i = 1; i < n - 1; i++) t[i] = m[i - 1] * m[i] <= 0 ? 0 : (m[i - 1] + m[i]) / 2
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0
      t[i + 1] = 0
      continue
    }
    const a = t[i] / m[i]
    const b = t[i + 1] / m[i]
    const s = a * a + b * b
    if (s > 9) {
      const k = 3 / Math.sqrt(s)
      t[i] = k * a * m[i]
      t[i + 1] = k * b * m[i]
    }
  }
  const out: Pt[] = [[pts[0][0], pts[0][1]]]
  for (let i = 0; i < n - 1; i++) {
    const cnt = Math.max(2, Math.ceil(dx[i] / step))
    for (let k = 1; k <= cnt; k++) {
      const u = k / cnt
      const u2 = u * u
      const u3 = u2 * u
      const h00 = 2 * u3 - 3 * u2 + 1
      const h10 = u3 - 2 * u2 + u
      const h01 = -2 * u3 + 3 * u2
      const h11 = u3 - u2
      out.push([pts[i][0] + dx[i] * u, h00 * pts[i][1] + h10 * dx[i] * t[i] + h01 * pts[i + 1][1] + h11 * dx[i] * t[i + 1]])
    }
  }
  return out
}

export function stepCurve(pts: Pt[]): Pt[] {
  const out: Pt[] = []
  pts.forEach((p, i) => {
    if (i > 0) out.push([p[0], pts[i - 1][1]])
    out.push([p[0], p[1]])
  })
  return out
}

export function lttb(pts: Pt[], threshold: number): number[] {
  const n = pts.length
  if (threshold >= n || threshold < 3) return pts.map((_, i) => i)
  const keep: number[] = [0]
  const every = (n - 2) / (threshold - 2)
  let a = 0
  for (let i = 0; i < threshold - 2; i++) {
    const s0 = Math.floor((i + 1) * every) + 1
    const s1 = Math.min(Math.floor((i + 2) * every) + 1, n)
    let ax = 0
    let ay = 0
    for (let j = s0; j < s1; j++) {
      ax += pts[j][0]
      ay += pts[j][1]
    }
    const c = Math.max(1, s1 - s0)
    ax /= c
    ay /= c
    const r0 = Math.floor(i * every) + 1
    const r1 = Math.min(Math.floor((i + 1) * every) + 1, n)
    let best = -1
    let pick = r0
    for (let j = r0; j < r1; j++) {
      const area = Math.abs((pts[a][0] - ax) * (pts[j][1] - pts[a][1]) - (pts[a][0] - pts[j][0]) * (ay - pts[a][1]))
      if (area > best) {
        best = area
        pick = j
      }
    }
    keep.push(pick)
    a = pick
  }
  keep.push(n - 1)
  return keep
}

export function thinIndices(n: number, max: number): number[] {
  if (n <= max || max < 2) return Array.from({ length: n }, (_, i) => i)
  const out: number[] = []
  for (let k = 0; k < max; k++) out.push(Math.round((k * (n - 1)) / (max - 1)))
  return [...new Set(out)]
}

export function strideIndices(n: number, max: number): number[] {
  const k = Math.max(1, Math.ceil(n / Math.max(1, max)))
  const out: number[] = []
  for (let i = 0; i < n; i += k) out.push(i)
  return out
}

import type { Pt } from '@/lib/ink/types'
import { bucketOf, clampN, clearLabels, isNum, labelWidth, lttb, monotoneCurve, pickLabelIndices, stepCurve, strideIndices, textWidth, type Bucket, type LabelFont } from '@/lib/ink/charts/chart-scale'
import type { AxisTick, ChartLabel, ChartLayoutBase, CursorSpec, NotePen, XYSeries, XYSpec } from '@/lib/ink/charts/chart-types'

export interface XYBar {
  s: number
  i: number
  x: number
  y: number
  w: number
  h: number
  v: number
  neg: boolean
}
export interface XYLine {
  s: number
  segs: Pt[][]
  pts: Array<Pt | null>
}
export interface XYArea {
  s: number
  polys: Pt[][]
}
export interface XYDot {
  s: number
  i: number
  x: number
  y: number
  r: number
  last: boolean
}
export interface XYNoteGeom {
  n: number
  pen: NotePen
  shape: 'loop' | 'underline' | 'none'
  loop: { cx: number; cy: number; rx: number; ry: number } | null
  underline: { x1: number; x2: number; y: number } | null
  arrow: { x1: number; y1: number; x2: number; y2: number } | null
}
export interface XYBandGeom {
  x: number
  y: number
  w: number
  h: number
}
export interface XYRefGeom {
  x1: number
  y1: number
  x2: number
  y2: number
  pen: NotePen
}

export interface XYLayout extends ChartLayoutBase {
  plot: { x0: number; y0: number; x1: number; y1: number }
  horizontal: boolean
  band: number
  gridPx: number[]
  basePx: number
  bars: XYBar[]
  lines: XYLine[]
  areas: XYArea[]
  dots: XYDot[]
  notes: XYNoteGeom[]
  refs: XYRefGeom[]
  bands: XYBandGeom[]
  barW: number
  pointOf: Array<{ s: number; j: number }>
  simplified: number
}

export const XY_MARGINS = { top: 12, right: 12 }

export function isHorizontal(spec: XYSpec): boolean {
  return spec.horizontal && spec.series.length > 0 && spec.series.every((s) => s.kind === 'bar')
}

export function stackRanges(series: XYSeries[], stacked: boolean, n: number): Array<Array<[number, number] | null>> {
  const out: Array<Array<[number, number] | null>> = series.map(() => new Array(n).fill(null))
  if (!stacked) {
    series.forEach((s, k) => {
      for (let i = 0; i < n; i++) {
        const v = s.values[i]
        if (isNum(v)) out[k][i] = v >= 0 ? [0, v] : [v, 0]
      }
    })
    return out
  }
  for (let i = 0; i < n; i++) {
    let pos = 0
    let neg = 0
    series.forEach((s, k) => {
      const v = s.values[i]
      if (!isNum(v)) return
      if (v >= 0) {
        out[k][i] = [pos, pos + v]
        pos += v
      } else {
        out[k][i] = [neg + v, neg]
        neg += v
      }
    })
  }
  return out
}

interface Metrics {
  font: LabelFont
  tick: number
  value: number
  note: number
}

function metricsFor(bucket: Bucket, calm: boolean): Metrics {
  if (calm) return { font: 'hand', tick: 12.5, value: 12, note: 15 }
  return { font: 'script', tick: bucket === 'sm' ? 14 : bucket === 'md' ? 15 : 16, value: bucket === 'lg' ? 16 : 15, note: bucket === 'sm' ? 18 : 20 }
}

const dist = (a: Pt, b: Pt): number => Math.hypot(a[0] - b[0], a[1] - b[1])

const isNiceStep = (t: readonly AxisTick[]): boolean => {
  if (t.length < 2) return true
  const st = Math.abs(t[1].v - t[0].v)
  if (!(st > 0)) return true
  const m = st / 10 ** Math.floor(Math.log10(st))
  return [1, 2, 5, 10].some((x) => Math.abs(m - x) < 1e-6)
}

export function pickTicks(dense: readonly AxisTick[], alt: readonly (readonly AxisTick[])[] | undefined, max: number, span: readonly [number, number]): AxisTick[] {
  if (dense.length <= max) return [...dense]
  const eps = Math.abs(span[1] - span[0]) * 1e-6
  const fits = (alt ?? []).filter((t) => t.length >= 2 && t.length <= max)
  const reaches = (t: readonly AxisTick[]) => Math.abs(t[0].v - span[0]) <= eps && Math.abs(t[t.length - 1].v - span[1]) <= eps
  const most = (sets: readonly (readonly AxisTick[])[]) => sets.reduce<readonly AxisTick[] | null>((b, t) => (!b || t.length > b.length ? t : b), null)
  const ends = most(fits.filter(reaches))
  if (ends) return [...ends]
  const stride = strideIndices(dense.length, max).map((i) => dense[i])
  if (isNiceStep(stride)) return stride
  const other = most(fits)
  return other ? [...other] : stride
}

function sampleSeries(pts: Array<Pt | null>, curve: XYSpec['curve']): Pt[][] {
  const runs: Pt[][] = []
  let cur: Pt[] = []
  for (const p of pts) {
    if (p) cur.push(p)
    else if (cur.length) {
      runs.push(cur)
      cur = []
    }
  }
  if (cur.length) runs.push(cur)
  return runs.map((r) => (r.length < 2 ? r : curve === 'smooth' ? monotoneCurve(r, 4) : curve === 'step' ? stepCurve(r) : r))
}

export function layoutXY(spec: XYSpec, box: { w: number; h: number }, calm = false): XYLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const M = metricsFor(bucket, calm)
  const horizontal = isHorizontal(spec)
  const scatter = spec.series.some((s) => s.kind === 'scatter')
  const n = spec.cats.length
  const hasBars = spec.series.some((s) => s.kind === 'bar')
  const labels: ChartLabel[] = []
  const empty = spec.state !== 'ready' || (!scatter && n === 0) || spec.series.length === 0

  const maxYTicks = horizontal ? Math.max(2, Math.floor((w * 0.7) / 54)) : Math.max(2, Math.floor((h - 60) / 38))
  const yTicks = pickTicks(spec.yTicks, spec.yTicksAlt, bucket === 'sm' && !horizontal ? Math.min(3, maxYTicks) : maxYTicks + 1, [spec.yMin, spec.yMax])
  const catW = horizontal ? Math.max(0, ...spec.cats.map((c) => textWidth(c, M.tick, M.font))) : 0
  const yLabelW = horizontal ? Math.min(catW, w * 0.36) : Math.max(0, ...yTicks.map((t) => textWidth(t.label, M.tick, M.font)))
  const left = spec.showY ? Math.ceil(yLabelW) + 12 : 6
  const fitsValues = (): boolean => {
    if (!spec.valueLabels || spec.values === false) return false
    if (spec.values === true) return true
    if (spec.stacked || bucket === 'sm') return false
    const barSeriesCount = spec.series.filter((s) => s.kind === 'bar').length
    if (!barSeriesCount) return false
    const slotLen = (horizontal ? h : w) / Math.max(1, spec.cats.length) / (spec.stacked ? 1 : barSeriesCount)
    const widest = Math.max(1, ...spec.valueLabels.flat().map((t) => (t ? textWidth(t, M.value, M.font) : 0)))
    return horizontal ? slotLen >= M.value : slotLen >= 28 && widest <= slotLen * 0.75
  }
  const wantsValues = !empty && fitsValues()
  const top = XY_MARGINS.top + (wantsValues && !horizontal ? M.value + 2 : 0) + (spec.notes.length ? 6 : 0)
  const bottom = spec.showX ? Math.round(M.tick + 14) : 8
  const right = XY_MARGINS.right + (horizontal && wantsValues ? 26 : 0)
  const x0 = left
  const x1 = Math.max(x0 + 10, w - right)
  const y0 = top
  const y1 = Math.max(y0 + 10, h - bottom)
  const plotW = x1 - x0
  const plotH = y1 - y0

  const catLen = horizontal ? plotH : plotW
  const band = n > 0 ? catLen / n : catLen

  const vMin = scatter || !horizontal ? spec.yMin : spec.yMin
  const vSpan = spec.yMax - vMin || 1
  const vPos = (v: number): number => (horizontal ? clampN(x0 + ((v - vMin) / vSpan) * plotW, x0 - 6, x1 + 6) : clampN(y1 - ((v - vMin) / vSpan) * plotH, y0 - 6, y1 + 6))
  const basePx = vPos(clampN(0, vMin, spec.yMax))

  const centered = hasBars || horizontal
  const inset = clampN(band * 0.5, 8, 26)
  const catPos = (i: number): number => {
    if (horizontal) return y0 + band * (i + 0.5)
    if (centered || n < 2) return x0 + band * (i + 0.5)
    return x0 + inset + ((plotW - 2 * inset) * i) / (n - 1)
  }
  const xMin = spec.xMin ?? 0
  const xSpan = (spec.xMax ?? 1) - xMin || 1
  const xNum = (v: number): number => clampN(x0 + ((v - xMin) / xSpan) * plotW, x0 - 6, x1 + 6)

  const bars: XYBar[] = []
  const barSeries = spec.series.map((s, k) => ({ s, k })).filter((e) => e.s.kind === 'bar')
  const ranges = stackRanges(barSeries.map((e) => e.s), spec.stacked, n)
  const m = spec.stacked ? 1 : Math.max(1, barSeries.length)
  const ratio = bucket === 'sm' ? 0.72 : bucket === 'md' ? 0.66 : 0.6
  const room = band * ratio
  const gap = m > 1 ? Math.max(0, Math.min(bucket === 'sm' ? 2 : 3, (room - m * 2.5) / (m - 1))) : 0
  const barW = clampN((room - gap * (m - 1)) / m, 1, 58)
  const groupW = m * barW + gap * (m - 1)
  if (!empty) {
    barSeries.forEach((e, bi) => {
      for (let i = 0; i < n; i++) {
        const r = ranges[bi][i]
        if (!r) continue
        const c = catPos(i)
        const off = spec.stacked ? 0 : bi
        const a = c - groupW / 2 + off * (barW + gap)
        const lo = vPos(r[0])
        const hi = vPos(r[1])
        const v = e.s.values[i] as number
        if (horizontal) bars.push({ s: e.k, i, x: Math.min(lo, hi), y: a, w: Math.abs(hi - lo), h: barW, v, neg: v < 0 })
        else bars.push({ s: e.k, i, x: a, y: Math.min(lo, hi), w: barW, h: Math.abs(hi - lo), v, neg: v < 0 })
      }
    })
  }

  const lines: XYLine[] = []
  const areas: XYArea[] = []
  let simplified = 0
  const maxPts = Math.max(24, Math.round(plotW / 3))
  const lineSeries = spec.series.map((s, k) => ({ s, k })).filter((e) => e.s.kind === 'line' || e.s.kind === 'area')
  const areaSeries = lineSeries.filter((e) => e.s.kind === 'area')
  const areaRanges = stackRanges(areaSeries.map((e) => e.s), spec.stacked, n)
  if (!empty && !scatter) {
    lineSeries.forEach((e) => {
      const ai = areaSeries.findIndex((a) => a.k === e.k)
      const stackedArea = spec.stacked && ai >= 0
      const pts: Array<Pt | null> = []
      for (let i = 0; i < n; i++) {
        const v = e.s.values[i]
        if (!isNum(v)) {
          pts.push(null)
          continue
        }
        const top = stackedArea ? (areaRanges[ai][i]?.[1] ?? 0) : v
        const val = stackedArea && v < 0 ? (areaRanges[ai][i]?.[0] ?? 0) : top
        pts.push([catPos(i), vPos(val)])
      }
      let use = pts
      if (n > maxPts) {
        let last = 0
        const filled = pts.map((p, i) => {
          if (p) last = p[1]
          return [i, p ? p[1] : last] as Pt
        })
        const keep = new Set(lttb(filled, maxPts))
        pts.forEach((p, i) => {
          if (p !== null) return
          keep.add(i)
          if (i > 0) keep.add(i - 1)
          if (i < n - 1) keep.add(i + 1)
        })
        const order = [...keep].sort((x, y) => x - y)
        use = order.map((i) => pts[i])
        simplified = Math.max(simplified, n - order.length)
      }
      const segs = sampleSeries(use, spec.curve)
      lines.push({ s: e.k, segs, pts })
      if (e.s.kind === 'area') {
        const polys: Pt[][] = []
        segs.forEach((seg) => {
          if (seg.length < 2) return
          let lower: Pt[]
          if (stackedArea && ai > 0) {
            const below = lines.find((l) => l.s === areaSeries[ai - 1].k)
            lower = below ? sampleSeries(below.pts, spec.curve).flat().filter((p) => p[0] >= seg[0][0] - 0.01 && p[0] <= seg[seg.length - 1][0] + 0.01).reverse() : []
          } else lower = [[seg[seg.length - 1][0], basePx], [seg[0][0], basePx]]
          if (!lower.length) lower = [[seg[seg.length - 1][0], basePx], [seg[0][0], basePx]]
          polys.push([...seg, ...lower])
        })
        areas.push({ s: e.k, polys })
      }
    })
  }

  const dots: XYDot[] = []
  const pointOf: Array<{ s: number; j: number }> = []
  const tx: number[] = []
  const ty: number[] = []
  const lineCount = lines.length
  const showDots = !scatter && lineCount > 0 && (spec.dots === true || (spec.dots === 'auto' && n <= 24 && catLen / Math.max(1, n) >= 15 && lineCount <= 4))
  if (showDots) {
    for (const l of lines) {
      const ser = spec.series[l.s]
      if (ser.kind === 'area' && spec.dots === 'auto' && lineCount > 1) continue
      l.pts.forEach((p, i) => {
        if (p) dots.push({ s: l.s, i, x: p[0], y: p[1], r: 3.4, last: i === n - 1 })
      })
    }
  }

  if (scatter && !empty) {
    const maxPoints = 600
    spec.series.forEach((ser, k) => {
      if (ser.kind !== 'scatter' || !ser.xs) return
      const cnt = Math.min(ser.values.length, ser.xs.length)
      const stride = Math.max(1, Math.ceil(cnt / (maxPoints / Math.max(1, spec.series.length))))
      const smax = Math.max(1, ...(ser.sizes ?? []).filter(isNum))
      if (stride > 1) simplified = Math.max(simplified, cnt - Math.ceil(cnt / stride))
      for (let j = 0; j < cnt; j += stride) {
        const yv = ser.values[j]
        const xv = ser.xs[j]
        if (!isNum(yv) || !isNum(xv)) continue
        const sz = ser.sizes?.[j]
        const r = isNum(sz) ? 3 + 9 * Math.sqrt(Math.max(0, sz) / smax) : 4.2
        const px = xNum(xv)
        const py = vPos(yv)
        dots.push({ s: k, i: j, x: px, y: py, r, last: false })
        pointOf.push({ s: k, j })
        tx.push(px)
        ty.push(py)
      }
    })
  }

  const gridPx: number[] = []
  if (!empty) {
    if (horizontal) {
      const bottomTicks: Array<{ t: AxisTick; x: number; w: number }> = []
      for (const t of yTicks) {
        const x = vPos(t.v)
        gridPx.push(x)
        bottomTicks.push({ t, x, w: labelWidth(t.label, M.tick, M.font) })
      }
      if (spec.showX) for (const { t, x } of clearLabels(bottomTicks)) labels.push({ id: `y-${t.v}`, text: t.label, x, y: y1 + 8, anchor: 'middle', valign: 'top', role: 'y', size: M.tick, tone: 'muted' })
      if (spec.showY) {
        const stride = Math.max(1, Math.ceil((M.tick + 4) / Math.max(4, band)))
        for (let i = 0; i < n; i += stride) labels.push({ id: `c-${i}`, text: spec.cats[i], x: x0 - 8, y: catPos(i), anchor: 'end', valign: 'middle', role: 'cat', size: M.tick, tone: 'ink', maxW: left - 12 })
      }
    } else {
      for (const t of yTicks) {
        const y = vPos(t.v)
        gridPx.push(y)
        if (spec.showY) labels.push({ id: `y-${t.v}`, text: t.label, x: x0 - 8, y, anchor: 'end', valign: 'middle', role: 'y', size: M.tick, tone: 'muted' })
      }
      if (spec.showX && scatter && spec.xTicks) {
        const xt = pickTicks(spec.xTicks, spec.xTicksAlt, Math.max(2, Math.floor(plotW / 64)), [spec.xMin ?? 0, spec.xMax ?? 1]).map((t) => ({ t, x: xNum(t.v), w: labelWidth(t.label, M.tick, M.font) }))
        for (const { t, x } of clearLabels(xt)) labels.push({ id: `x-${t.v}`, text: t.label, x, y: y1 + 8, anchor: 'middle', valign: 'top', role: 'x', size: M.tick, tone: 'ink' })
      } else if (spec.showX && !scatter && n > 0) {
        const pitch = n > 1 ? (catPos(n - 1) - catPos(0)) / (n - 1) : band
        const { idx, stride } = pickLabelIndices(spec.cats.map((c) => labelWidth(c, M.tick, M.font)), pitch)
        for (const i of idx) {
          labels.push({ id: `x-${i}`, text: spec.cats[i], x: catPos(i), y: y1 + 8, anchor: 'middle', valign: 'top', role: 'x', size: M.tick, tone: 'ink', maxW: Math.max(pitch * stride, 12) })
        }
      }
    }
  }

  if (wantsValues && spec.valueLabels) {
    for (const b of bars) {
      const text = spec.valueLabels[b.s]?.[b.i]
      if (!text) continue
      if (horizontal) labels.push({ id: `v-${b.s}-${b.i}`, text, x: b.neg ? b.x - 5 : b.x + b.w + 5, y: b.y + b.h / 2, anchor: b.neg ? 'end' : 'start', valign: 'middle', role: 'value', size: M.value, tone: 'ink' })
      else labels.push({ id: `v-${b.s}-${b.i}`, text, x: b.x + b.w / 2, y: b.neg ? b.y + b.h + 4 : b.y - 4, anchor: 'middle', valign: b.neg ? 'top' : 'bottom', role: 'value', size: M.value, tone: 'ink' })
    }
  }

  const bands: XYBandGeom[] = []
  if (!empty && !scatter) {
    spec.bands.forEach((b, bi) => {
      const lo = catPos(b.i0) - (centered ? band / 2 : Math.min(band / 2, 14))
      const hi = catPos(b.i1) + (centered ? band / 2 : Math.min(band / 2, 14))
      const g: XYBandGeom = horizontal ? { x: x0, y: lo, w: plotW, h: hi - lo } : { x: lo, y: y0, w: hi - lo, h: plotH }
      bands.push(g)
      if (b.text) labels.push({ id: `band-${bi}`, text: b.text, x: horizontal ? x1 - 4 : g.x + 5, y: horizontal ? g.y + 4 : y0 + 3, anchor: horizontal ? 'end' : 'start', valign: 'top', role: 'note', size: M.tick, tone: 'ink' })
    })
  }

  const notes: XYNoteGeom[] = []
  spec.notes.forEach((note, ni) => {
    let target: Pt | null = null
    let rx = 11
    let ry = 10
    const bar = bars.find((b) => b.s === note.s && b.i === note.i)
    const dot = dots.find((d) => d.s === note.s && d.i === note.i)
    const linePt = lines.find((l) => l.s === note.s)?.pts[note.i]
    if (bar) {
      const labelled = wantsValues && !!spec.valueLabels?.[bar.s]?.[bar.i]
      target = horizontal ? [bar.neg ? bar.x : bar.x + bar.w + (labelled ? 12 : 0), bar.y + bar.h / 2] : [bar.x + bar.w / 2, (bar.neg ? bar.y + bar.h : bar.y) - (labelled ? M.value * 0.7 : 0)]
      rx = horizontal ? (labelled ? 18 : 10) : Math.max(labelled ? 15 : 11, bar.w / 2 + 7)
      ry = horizontal ? Math.max(10, bar.h / 2 + 6) : labelled ? 15 : 10
    } else if (dot) {
      target = [dot.x, dot.y]
      rx = ry = dot.r + 7
    } else if (linePt) target = linePt
    if (!target) return
    const tw = textWidth(note.text, M.note, M.font)
    const th = M.note * 1.1
    const tgt = target
    const crowd = (l0: number, t0: number, l1: number, t1: number): number => {
      let hits = 0
      for (const l of lines) for (const sg of l.segs) for (let k = 0; k < sg.length; k += 2) if (sg[k][0] >= l0 && sg[k][0] <= l1 && sg[k][1] >= t0 && sg[k][1] <= t1) hits++
      for (const b of bars) {
        const ox = Math.min(l1, b.x + b.w) - Math.max(l0, b.x)
        const oy = Math.min(t1, b.y + b.h) - Math.max(t0, b.y)
        if (ox > 0 && oy > 0) hits += 3 + (ox * oy) / 40
      }
      for (const d of dots) if (d.x >= l0 && d.x <= l1 && d.y >= t0 && d.y <= t1) hits += 2
      for (const a of areas) {
        const l = lines.find((q) => q.s === a.s)
        if (!l) continue
        const mx = (l0 + l1) / 2
        for (const sg of l.segs) {
          const i = sg.findIndex((p) => p[0] >= mx)
          if (i > 0 && sg[i][0] > sg[i - 1][0]) {
            const t = (mx - sg[i - 1][0]) / (sg[i][0] - sg[i - 1][0])
            const yc = sg[i - 1][1] + (sg[i][1] - sg[i - 1][1]) * t
            if (t1 > yc - 2) hits += 5
          }
        }
      }
      for (const q of labels) {
        if (q.role === 'note' || q.role === 'center') continue
        const qw = textWidth(q.text, q.size ?? M.tick, M.font)
        const qx0 = q.anchor === 'start' ? q.x : q.anchor === 'end' ? q.x - qw : q.x - qw / 2
        const qy0 = q.valign === 'top' ? q.y : q.valign === 'bottom' ? q.y - (q.size ?? M.tick) : q.y - (q.size ?? M.tick) / 2
        if (qx0 < l1 && qx0 + qw > l0 && qy0 < t1 && qy0 + (q.size ?? M.tick) > t0) hits += 6
      }
      return hits
    }
    const pinned = note.dx !== undefined || note.dy !== undefined
    const up = -38
    const down = 44 + th
    const near = tw / 2 + 40
    const cands: Array<[number, number]> = pinned ? [[note.dx ?? near, note.dy ?? up]] : [[near, up], [-near, up], [near, -28], [-near, -28], [near, down], [-near, down], [0, up - 14], [0, down + 12]]
    let best = { lx: 0, ly: 0, score: Infinity }
    cands.forEach(([cdx, cdy], ci) => {
      const rawX = tgt[0] + cdx
      const rawY = tgt[1] + cdy
      const cx = clampN(rawX, Math.min(x0 + tw / 2 + 2, w / 2), w - tw / 2 - 4)
      const cy = clampN(rawY, th + 2, h - 4)
      const score = Math.abs(cx - rawX) * 0.35 + Math.abs(cy - rawY) * 0.35 + crowd(cx - tw / 2 - 3, cy - th - 2, cx + tw / 2 + 3, cy + 4) * 2 + ci * 0.4
      if (score < best.score) best = { lx: cx, ly: cy, score }
    })
    const lx = best.lx
    const ly = best.ly
    const dx = lx - tgt[0]
    const dy = ly - tgt[1]
    const sx = lx + (dx > 0 ? -tw / 2 - 4 : tw / 2 + 4)
    const sy = ly - (dy < 0 ? -2 : th + 2)
    const ang = Math.atan2(sy - target[1], sx - target[0])
    const ex = target[0] + Math.cos(ang) * (rx + 3)
    const ey = target[1] + Math.sin(ang) * (ry + 3)
    const far = dist([sx, sy], [ex, ey]) > 14
    labels.push({ id: `note-${ni}`, text: note.text, x: lx, y: ly, anchor: 'middle', valign: 'bottom', role: 'note', size: M.note, tone: note.pen === 'red' ? 'red' : note.pen === 'green' ? 'green' : note.pen === 'blue' ? 'blue' : 'ink' })
    notes.push({
      n: ni,
      pen: note.pen,
      shape: note.shape,
      loop: note.shape === 'loop' ? { cx: target[0], cy: target[1], rx, ry } : null,
      underline: note.shape === 'underline' ? { x1: lx - tw / 2 - 2, x2: lx + tw / 2 + 2, y: ly + 3 } : null,
      arrow: far ? { x1: sx, y1: sy, x2: ex, y2: ey } : null,
    })
  })

  const refs: XYRefGeom[] = []
  if (!empty) {
    spec.refs.forEach((r, ri) => {
      if (r.axis === 'y') {
        const p = vPos(r.value)
        if (horizontal) {
          refs.push({ x1: p, y1: y0 - 2, x2: p, y2: y1, pen: r.pen })
          if (r.label) labels.push({ id: `ref-${ri}`, text: r.label, x: p + 4, y: y0 - 2, anchor: 'start', valign: 'bottom', role: 'ref', size: M.tick, tone: r.pen === 'red' ? 'red' : 'muted' })
        } else {
          refs.push({ x1: x0, y1: p, x2: x1, y2: p, pen: r.pen })
          if (r.label) labels.push({ id: `ref-${ri}`, text: r.label, x: x1 - 2, y: p - 3, anchor: 'end', valign: 'bottom', role: 'ref', size: M.tick, tone: r.pen === 'red' ? 'red' : 'muted' })
        }
      } else if (scatter) {
        const p = xNum(r.value)
        refs.push({ x1: p, y1: y0, x2: p, y2: y1, pen: r.pen })
        if (r.label) labels.push({ id: `ref-${ri}`, text: r.label, x: p + 4, y: y0 + 2, anchor: 'start', valign: 'top', role: 'ref', size: M.tick, tone: r.pen === 'red' ? 'red' : 'muted' })
      }
    })
  }

  if (spec.state !== 'ready' || (empty && spec.stateText)) {
    const at = spec.state === 'loading' ? 0.16 : 0.38
    labels.push({ id: 'state', text: spec.stateText ?? (spec.state === 'loading' ? 'Loading' : 'No data'), x: (x0 + x1) / 2, y: y0 + (y1 - y0) * at, anchor: 'middle', valign: 'middle', role: 'center', size: M.note, tone: 'muted' })
  }

  let targets: XYLayout['targets']
  if (scatter) {
    targets = { n: pointOf.length, mode: 'point', cx: tx, cy: ty, nav: 'linear' }
  } else {
    const pos: number[] = []
    const cx: number[] = []
    const cy: number[] = []
    for (let i = 0; i < n; i++) {
      const c = catPos(i)
      pos.push(c)
      let best = horizontal ? x0 : y1
      let seen = false
      for (const b of bars) if (b.i === i) {
        const edge = horizontal ? (b.neg ? b.x : b.x + b.w) : b.neg ? b.y + b.h : b.y
        best = seen ? (horizontal ? Math.max(best, edge) : Math.min(best, edge)) : edge
        seen = true
      }
      for (const l of lines) {
        const p = l.pts[i]
        if (p) {
          best = seen ? Math.min(best, p[1]) : p[1]
          seen = true
        }
      }
      if (horizontal) {
        cx.push(seen ? best : x0)
        cy.push(c)
      } else {
        cx.push(c)
        cy.push(seen ? best : y1)
      }
    }
    targets = { n, mode: horizontal ? 'y' : 'x', pos, cx, cy, nav: 'linear' }
  }

  const cursorAt = (i: number, series?: number | null): CursorSpec[] => {
    const out: CursorSpec[] = []
    if (i < 0 || i >= targets.n) return out
    if (scatter) {
      const d = dots.find((q) => q.s === pointOf[i].s && q.i === pointOf[i].j)
      if (d) out.push({ kind: 'ring', x: d.x - d.r - 6, y: d.y - d.r - 6, w: 2 * d.r + 12, h: 2 * d.r + 12, slot: spec.series[d.s].slot })
      return out
    }
    const c = targets.pos?.[i] ?? 0
    if (hasBars) {
      out.push(horizontal ? { kind: 'column', x: x0, y: c - band / 2, w: plotW, h: band } : { kind: 'column', x: c - band / 2, y: y0, w: band, h: plotH })
    } else if (!horizontal) {
      out.push({ kind: 'guide', x: c - 5, y: y0, w: 10, h: plotH })
    }
    if (!horizontal) {
      for (const l of lines) {
        if (series != null && series !== l.s) continue
        const p = l.pts[i]
        if (p) out.push({ kind: 'ring', x: p[0] - 9, y: p[1] - 9, w: 18, h: 18, slot: spec.series[l.s].slot })
      }
    }
    return out
  }

  return { w, h, bucket, labels, targets, cursorAt, plot: { x0, y0, x1, y1 }, horizontal, band, gridPx, basePx, bars, lines, areas, dots, notes, refs, bands, barW, pointOf, simplified }
}

import { blobFill } from '@/lib/ink/fills'
import { seg } from '@/lib/ink/geom'
import { box, loop } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { arcPts, sectorPoly } from '@/lib/ink/charts/chart-polar'
import { slotKey, type MiniParams } from '@/lib/ink/charts/chart-types'
import { hatchOn } from '@/lib/ink/recipes/chart-ink/xy'
import { drawMarker, drawPolyline, patternFill, rectPts, swipeFill } from '@/lib/ink/recipes/chart-ink/parts'
import type { Pt } from '@/lib/ink/types'

export const markRecipe = defineRecipe<MiniParams>({
  id: 'chart-mark',
  kind: 'chart',
  layers: ['rest'],
  pad: 10,
  draw(ink, { w, h }, p, ctx) {
    const calm = ctx.calm
    ink.layer('rest', () => {
      switch (p.kind) {
        case 'swatch': {
          const key = slotKey(p.slot)
          if (p.line) {
            const y = h / 2
            drawPolyline(ink, [[1, y + 0.5], [w * 0.5, y - 0.4], [w - 1, y]], p.dash ?? 'solid', 'ink', { color: key, width: 1.15, simple: true })
            if (p.marker && p.marker !== 'none') drawMarker(ink, p.marker, w / 2, y, Math.min(w, h) * 0.3, { color: key, rich: false, pen: 'ink.fine' })
            return
          }
          const s = Math.min(w, h)
          const x0 = (w - s) / 2
          const y0 = (h - s) / 2
          ink.part('fill', () => blobFill(ink, rectPts(x0 + 1, y0 + 1, s - 2, s - 2), key, { alpha: 0.9, mis: calm ? false : 0.9, rough: 0.25 }))
          if (p.pattern !== 'solid') patternFill(ink, p.pattern, rectPts(x0 + 2, y0 + 2, s - 4, s - 4), { color: hatchOn(p.slot), maxPulls: 9, alpha: 0.75, gapK: 0.62 })
          box(ink, x0, y0, s, s, { pen: 'ink.fine', corner: 1.5, style: 'two', stubs: false, ghost: false, opts: { simple: true, width: 1 } })
          return
        }
        case 'column':
          swipeFill(ink, { x: 1.5, y: 1.5, w: w - 3, h: h - 3 }, w > h, calm)
          return
        case 'guide': {
          const x = w / 2
          const gap = 11
          for (let y = 2; y < h - 4; y += gap) ink.stroke(seg(x + Math.sin(y) * 0.4, y, x + Math.sin(y + 1) * 0.4, Math.min(h - 2, y + gap * 0.62), 0, 2), 'pencil', { simple: true, alpha: 0.75, width: 0.95, start: 'soft', end: 'soft' })
          return
        }
        case 'ring':
          loop(ink, w / 2, h / 2, w / 2 - 2, h / 2 - 2.3, { pen: 'ink', opts: { color: slotKey(p.slot), width: 0.95, simple: true }, turns: 1.1 })
          return
        case 'slice': {
          const poly = sectorPoly(p.cx, p.cy, p.r0, p.r1, p.a0, p.a1, 5)
          blobFill(ink, poly, 'hi', { alpha: 0.26, mis: false, rough: 0.6 })
          const edge: Pt[] = [...arcPts(p.cx, p.cy, p.r1, p.a0, p.a1, 4), ...arcPts(p.cx, p.cy, Math.max(0.5, p.r0), p.a1, p.a0, 4)]
          ink.stroke([...edge, edge[0], edge[1]], 'ink', { poly: true, round: 1.5, width: 1.1, simple: true, wobble: 0.5, end: 'flick' })
          return
        }
        case 'cell':
          blobFill(ink, rectPts(2, 2, w - 4, h - 4), 'hi', { alpha: 0.22, mis: false, rough: 0.5 })
          box(ink, 1, 1, w - 2, h - 2, { pen: 'ink', corner: 2, style: 'two', stubs: false, ghost: false, opts: { simple: true, width: 1 } })
          return
        case 'spoke':
          ink.stroke(seg(p.x1, p.y1, p.x2, p.y2, 0.6, 8), 'hi', { width: 0.7, alpha: 0.9, start: 'soft', end: 'soft' })
          return
      }
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import { wash } from '@/lib/ink/fills'
import { clamp } from '@/lib/ink/rng'
import { focusRing, line, tallyLines } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { layoutHeat, layoutSpark, layoutTally } from '@/lib/ink/charts/chart-mini'
import { slotKey, type HeatSpec, type SparkSpec, type TallySpec } from '@/lib/ink/charts/chart-types'
import { drawPolyline } from '@/lib/ink/recipes/chart-ink/parts'
import type { PaintKey } from '@/lib/ink/paint'
import type { Pt } from '@/lib/ink/types'

export function roughSquare(ink: Ink, x: number, y: number, w: number, h: number, amt: number): string {
  const r = ink.next('cell')
  if (amt <= 0) return `M${+x.toFixed(1)} ${+y.toFixed(1)}h${+w.toFixed(1)}v${+h.toFixed(1)}h${+(-w).toFixed(1)}z`
  const j = () => r.gauss(0, amt)
  const p = (a: number, b: number) => `${(a + j()).toFixed(1)} ${(b + j()).toFixed(1)}`
  return `M${p(x, y)}L${p(x + w, y)} ${p(x + w, y + h)} ${p(x, y + h)}z`
}

export const sparkRecipe = defineRecipe<SparkSpec>({
  id: 'chart-spark',
  kind: 'chart',
  layers: ['rest', 'focus'],
  lazy: ['focus'],
  pad: 8,
  draw(ink, box, spec, ctx) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, box.w, box.h, { r: 4 }))
    if (ctx.lazyOnly) return
    const L = layoutSpark(spec, box)
    const key = slotKey(spec.slot)
    const calm = ctx.calm
    ink.layer('rest', () => {
      if (spec.state !== 'ready' || !L.pts.some(Boolean)) {
        line(ink, 4, box.h / 2, box.w - 4, box.h / 2 - 0.6, { pen: 'pencil', single: true, opts: { simple: true, alpha: 0.6, width: 0.9 } })
        return
      }
      ink.group(
        { part: 'wipe' },
        () => {
          if (spec.variant === 'bar') {
            let d = ''
            for (const b of L.bars) d += roughSquare(ink, b.x, b.y, b.w, b.h, calm ? 0 : 0.35)
            ink.flat('marker', d, key, calm ? 0.8 : 0.9)
            return
          }
          if (spec.variant === 'area') {
            for (const s of L.segs) {
              if (s.length < 2) continue
              const poly: Pt[] = [...s, [s[s.length - 1][0], L.baseY], [s[0][0], L.baseY]]
              wash(ink, poly, key, { alpha: 0.28, shift: calm ? 0 : 0.9, inset: 0.3, wobble: 0.3 })
            }
          }
          for (const s of L.segs) {
            if (s.length < 2) continue
            drawPolyline(ink, s, 'solid', calm ? 'ink.fine' : 'ink', { color: key, width: calm ? 1 : 1.05, simple: true })
          }
          if (spec.extremes) {
            for (const p of [L.minPt, L.maxPt]) if (p) ink.dot(p[0], p[1], 1.9, 'ink', { color: 'pencil' })
          }
          if (spec.ends && L.last) ink.dot(L.last[0], L.last[1], calm ? 2.2 : 2.7, 'redfelt')
        },
        'top',
      )
    })
  },
})

export const tallyRecipe = defineRecipe<TallySpec>({
  id: 'chart-tally',
  kind: 'chart',
  layers: ['rest', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink, box, spec, ctx) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, box.w, box.h, { r: 6 }))
    if (ctx.lazyOnly) return
    const L = layoutTally(spec, box, ctx.calm)
    ink.layer('rest', () => {
      if (spec.state !== 'ready' || !L.rows.length) {
        line(ink, 8, box.h / 2, box.w - 8, box.h / 2 - 0.6, { pen: 'pencil', single: true, opts: { simple: true, alpha: 0.6, width: 0.9 } })
        return
      }
      for (const r of L.rows) {
        line(ink, L.markArea.x0 - 6, r.y + r.gh + 4, L.markArea.x1, r.y + r.gh + 3.4, { pen: 'pencil', single: true, bow: 0.004, opts: { simple: true, alpha: ctx.calm ? 0.3 : 0.38, width: 0.75, wobble: ctx.calm ? 0.2 : 1 } })
      }
      ink.group(
        { part: 'wipe' },
        () => {
          const heavy = L.rows.reduce((n, r) => n + r.marks, 0) > 60
          for (const r of L.rows) {
            const key: PaintKey = slotKey(spec.rows[r.index].slot)
            const t = tallyLines(ink.next('tally'), r.x, r.y, r.marks, r.gh)
            ink.lines(t.lines, ctx.calm ? 'ink.fine' : 'ink', { color: key, simple: heavy || ctx.calm, width: ctx.calm ? 1.1 : 1.25 })
          }
        },
        'top',
      )
    })
  },
})

export function heatAlpha(level: number, count: number): number {
  if (level <= 0) return 0.16
  return 0.26 + (0.68 * (level - 1)) / Math.max(1, count - 2)
}

export const heatRecipe = defineRecipe<HeatSpec>({
  id: 'chart-heat',
  kind: 'chart',
  layers: ['rest', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink, box, spec, ctx) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, box.w, box.h, { r: 6 }))
    if (ctx.lazyOnly) return
    const L = layoutHeat(spec, box, ctx.calm)
    const key = slotKey(spec.slot)
    const calm = ctx.calm
    ink.layer('rest', () => {
      if (spec.state !== 'ready' || !L.cells.length) {
        ink.group({ part: 'pulse' }, () => {
          let d = ''
          for (let i = 0; i < spec.cols * spec.rows; i++) d += roughSquare(ink, L.gx + (i % spec.cols) * L.cs, L.gy + Math.floor(i / spec.cols) * L.cs, L.cell, L.cell, 0.3)
          ink.flat('wash', d, 'pencil-mark', 0.2)
        }, 'top')
        return
      }
      const amt = calm || L.cell < 6 ? 0 : clamp(L.cell * 0.05, 0.2, 0.6)
      ink.group(
        { part: 'wipe' },
        () => {
          const byLevel: string[] = Array.from({ length: spec.levelCount }, () => '')
          for (const c of L.cells) byLevel[Math.min(spec.levelCount - 1, c.level)] += roughSquare(ink, c.x, c.y, L.cell, L.cell, amt)
          byLevel.forEach((d, lv) => {
            if (!d) return
            if (lv === 0) ink.flat('wash', d, 'pencil-mark', 0.2)
            else ink.flat('marker', d, key, calm ? heatAlpha(lv, spec.levelCount) * 0.9 : heatAlpha(lv, spec.levelCount))
          })
          if (L.legend) {
            let d0 = ''
            const per: string[] = Array.from({ length: spec.levelCount }, () => '')
            for (let lv = 0; lv < spec.levelCount; lv++) per[lv] += roughSquare(ink, L.legend.x + lv * (L.legend.cell + 3), L.legend.y, L.legend.cell, L.legend.cell, amt)
            void d0
            per.forEach((d, lv) => {
              if (lv === 0) ink.flat('wash', d, 'pencil-mark', 0.2)
              else ink.flat('marker', d, key, heatAlpha(lv, spec.levelCount))
            })
          }
        },
        'top',
      )
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import type { PaintKey } from '@/lib/ink/paint'
import { hatch, solidFill } from '@/lib/ink/fills'
import { bboxOf, inside, scanSpans, roundRectPoly } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { line, loop } from '@/lib/ink/shapes'
import { slotKey, type Dash, type MarkerShape, type NotePen, type Pattern } from '@/lib/ink/charts/chart-types'
import type { PenName, Pt } from '@/lib/ink/types'

export const rectPts = (x: number, y: number, w: number, h: number): Pt[] => [
  [x, y],
  [x + w, y],
  [x + w, y + h],
  [x, y + h],
]

export const NOTE_PEN: Record<NotePen, { std: PenName; fine: PenName }> = {
  red: { std: 'redfelt', fine: 'redfelt.fine' },
  blue: { std: 'blue', fine: 'blue.fine' },
  ink: { std: 'ink', fine: 'ink.fine' },
  green: { std: 'greenfelt', fine: 'greenfelt.fine' },
}

export const seriesColor = slotKey

export interface PatternOpts {
  color: PaintKey
  gapK?: number
  alpha?: number
  maxPulls?: number
}

function stippleIn(ink: Ink, poly: Pt[], gap: number, color: PaintKey, alpha: number, maxDots: number): void {
  const rng = ink.next('dots')
  const [x0, y0, x1, y1] = bboxOf(poly)
  const cols = Math.max(1, Math.floor((x1 - x0) / gap))
  const rows = Math.max(1, Math.floor((y1 - y0) / (gap * 0.87)))
  const stride = Math.max(1, Math.ceil((cols * rows) / maxDots))
  let d = ''
  let k = 0
  for (let r = 0; r <= rows; r++) {
    for (let c = 0; c <= cols; c++) {
      if (k++ % stride) continue
      const x = x0 + (c + (r % 2 ? 0.5 : 0.1)) * gap + rng.gauss(0, gap * 0.12)
      const y = y0 + (r + 0.4) * gap * 0.87 + rng.gauss(0, gap * 0.1)
      if (!inside(poly, x, y)) continue
      const s = 0.85 + rng() * 0.6
      d += `M${x.toFixed(1)} ${y.toFixed(1)}l${s.toFixed(1)} ${(-0.2 * s).toFixed(1)} ${(0.1 * s).toFixed(1)} ${s.toFixed(1)} ${(-s).toFixed(1)} ${(0.1 * s).toFixed(1)}z`
    }
  }
  ink.flat('pencil', d, color, alpha)
}

function scribbleIn(ink: Ink, poly: Pt[], gap: number, color: PaintKey, alpha: number, maxPulls: number): void {
  const rng = ink.next('scrib')
  const b = bboxOf(poly)
  const g = Math.max(gap, (b[3] - b[1]) / Math.max(4, maxPulls))
  const spans = scanSpans(poly, -0.34, g, rng, { even: false, jitter: 0.12 })
  const pts: Pt[] = []
  spans.forEach((sp, i) => {
    const [a, c] = i % 2 ? [sp.b, sp.a] : [sp.a, sp.b]
    pts.push([a[0] + rng.gauss(0, 0.4), a[1] + rng.gauss(0, 0.4)], [c[0] + rng.gauss(0, 0.4), c[1] + rng.gauss(0, 0.4)])
  })
  if (pts.length > 3) ink.stroke(pts, 'pencil', { poly: true, round: 1.2, simple: true, alpha, width: 0.85, wobble: 0.5, color })
}

export function patternFill(ink: Ink, pattern: Pattern, poly: Pt[], o: PatternOpts): void {
  if (pattern === 'solid' || poly.length < 3) return
  const b = bboxOf(poly)
  const w = b[2] - b[0]
  const h = b[3] - b[1]
  if (w < 5 || h < 5) return
  const alpha = o.alpha ?? 0.62
  const maxPulls = o.maxPulls ?? 60
  const base = 5 * (o.gapK ?? 1)
  const gapDiag = Math.max(base, (w + h) / maxPulls)
  const gapRule = Math.max(base, h / maxPulls)
  const opts = { color: o.color }
  if (pattern === 'hatch') hatch(ink, poly, { pen: 'pencil', angle: 58, gap: gapDiag, alpha, width: 0.8, over: 0.5, under: 1.2, opts })
  else if (pattern === 'cross') hatch(ink, poly, { pen: 'pencil', angle: 52, gap: gapDiag * 1.25, tones: 2, cross: 76, alpha, width: 0.75, over: 0.5, under: 1.2, opts })
  else if (pattern === 'lines') hatch(ink, poly, { pen: 'pencil', angle: 4, gap: gapRule * 1.15, alpha, width: 0.8, over: 0.6, under: 1.2, opts })
  else if (pattern === 'dots') stippleIn(ink, poly, base * 1.3, o.color, alpha + 0.12, maxPulls * 3)
  else scribbleIn(ink, poly, base * 0.9, o.color, alpha, maxPulls)
}

export interface MarkerOpts {
  color: PaintKey
  rich: boolean
  pen?: PenName
  width?: number
}

export function drawMarker(ink: Ink, shape: MarkerShape, x: number, y: number, r: number, o: MarkerOpts): void {
  if (shape === 'none') return
  const rng = ink.next('mk')
  const j = () => rng.gauss(0, r * 0.05)
  const pen = o.pen ?? 'ink.fine'
  const opts = { color: o.color, simple: !o.rich, width: o.width ?? 1.15, wobble: 0.5, start: 'soft' as const, end: 'soft' as const }
  if (shape === 'circle') {
    if (o.rich) loop(ink, x, y, r, r * 0.96, { pen, opts: { color: o.color, width: o.width ?? 1.15, simple: true }, turns: 1.1 })
    else ink.dot(x, y, r * 0.62, 'ink', { color: o.color })
    return
  }
  const c: Pt = [x, y]
  const at = (a: number, k = 1): Pt => [c[0] + Math.cos(a) * r * k + j(), c[1] + Math.sin(a) * r * k + j()]
  if (shape === 'square') {
    const s = r * 0.92
    ink.stroke([[x - s, y - s + j()], [x + s + j(), y - s], [x + s, y + s + j()], [x - s + j(), y + s], [x - s, y - s + r * 0.35]], pen, { ...opts, poly: true })
  } else if (shape === 'triangle') {
    const p = [at(-Math.PI / 2, 1.1), at(Math.PI / 6, 1.1), at((5 * Math.PI) / 6, 1.1)]
    ink.stroke([p[0], p[1], p[2], p[0], [p[1][0] - r * 0.3, p[1][1] - r * 0.4]], pen, { ...opts, poly: true })
  } else if (shape === 'diamond') {
    const p = [at(-Math.PI / 2, 1.2), at(0, 1), at(Math.PI / 2, 1.2), at(Math.PI, 1)]
    ink.stroke([p[0], p[1], p[2], p[3], p[0], [p[1][0] - r * 0.2, p[1][1] - r * 0.3]], pen, { ...opts, poly: true })
  } else if (shape === 'cross') {
    const s = r * 0.85
    ink.stroke([[x - s, y - s], [x + s, y + s + j()]], pen, { ...opts, end: 'flick' })
    ink.stroke([[x + s, y - s], [x - s, y + s + j()]], pen, { ...opts, end: 'flick' })
  } else {
    const s = r * 1.05
    ink.stroke([[x - s, y + j()], [x + s, y + j()]], pen, { ...opts, end: 'flick' })
    ink.stroke([[x + j(), y - s], [x + j(), y + s]], pen, { ...opts, end: 'flick' })
  }
}

function cumulative(pts: Pt[]): number[] {
  const out = [0]
  for (let i = 1; i < pts.length; i++) out.push(out[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]))
  return out
}

function slicePath(pts: Pt[], cum: number[], a: number, b: number): Pt[] {
  const out: Pt[] = []
  const at = (d: number): Pt => {
    let i = 1
    while (i < cum.length - 1 && cum[i] < d) i++
    const t = (d - cum[i - 1]) / (cum[i] - cum[i - 1] || 1)
    return [pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * t, pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * t]
  }
  out.push(at(a))
  for (let i = 0; i < pts.length; i++) if (cum[i] > a && cum[i] < b) out.push(pts[i])
  out.push(at(b))
  return out
}

export function drawPolyline(ink: Ink, pts: Pt[], dash: Dash, pen: PenName, opts: { color: PaintKey; width?: number; simple?: boolean; poly?: boolean; alpha?: number }): void {
  if (pts.length < 2) return
  const base = { color: opts.color, width: opts.width ?? 1, simple: opts.simple, alpha: opts.alpha, poly: opts.poly ?? true, wobble: 0.22, dry: 0 }
  if (dash === 'solid') {
    ink.stroke(pts, pen, { ...base, start: 'soft', end: 'soft' })
    return
  }
  const cum = cumulative(pts)
  const total = cum[cum.length - 1]
  const on = dash === 'dotted' ? 0.1 : dash === 'dashed' ? 11 : 12
  const off = dash === 'dotted' ? 6.5 : dash === 'dashed' ? 6 : 5
  let d = 0
  let k = 0
  while (d < total && k < 400) {
    if (dash === 'dotted') {
      const p = slicePath(pts, cum, d, Math.min(total, d + 0.6))
      ink.dot(p[0][0], p[0][1], 1.5 * (opts.width ?? 1), 'ink', { color: opts.color })
      d += on + off
    } else {
      const len = dash === 'dashdot' && k % 2 ? 1.2 : on
      const seg = slicePath(pts, cum, d, Math.min(total, d + len))
      if (seg.length >= 2 && len > 2) ink.stroke(seg, pen, { ...base, simple: true, start: 'soft', end: 'soft' })
      else if (seg.length) ink.dot(seg[0][0], seg[0][1], 1.5 * (opts.width ?? 1), 'ink', { color: opts.color })
      d += len + off
      k++
    }
  }
}

export interface AxisFrame {
  x0: number
  y0: number
  x1: number
  y1: number
}

export function drawGrid(ink: Ink, positions: number[], frame: AxisFrame, vertical: boolean, calm: boolean): void {
  for (const p of positions) {
    if (vertical) {
      if (Math.abs(p - frame.y1) < 1.5) continue
      line(ink, frame.x0 + 3, p, frame.x1, p, { pen: 'pencil.fine', bow: 0, opts: { alpha: 0.45, width: 0.8, simple: true, wobble: 0.12, dry: 0 } })
    } else {
      if (Math.abs(p - frame.x0) < 1.5) continue
      line(ink, p, frame.y0 - 2, p, frame.y1 - 2, { pen: 'pencil.fine', bow: 0, opts: { alpha: 0.45, width: 0.8, simple: true, wobble: 0.12, dry: 0 } })
    }
  }
}

export function drawAxisLines(ink: Ink, f: AxisFrame, o: { x: boolean; y: boolean; calm: boolean; zeroY?: number | null }): void {
  const penX: PenName = o.calm ? 'ink.fine' : 'ink.fine'
  if (o.x) line(ink, f.x0, f.y1, f.x1, f.y1, { pen: penX, single: true, bow: 0, opts: { simple: o.calm, width: o.calm ? 0.85 : 1.05, wobble: 0.15, dry: 0 } })
  if (o.y) line(ink, f.x0, f.y1, f.x0, f.y0 - 2, { pen: 'ink.fine', single: true, bow: 0, opts: { simple: o.calm, width: 0.9, wobble: 0.15, dry: 0, alpha: 0.8 } })
  if (o.zeroY != null && Math.abs(o.zeroY - f.y1) > 2) line(ink, f.x0, o.zeroY, f.x1, o.zeroY - (o.calm ? 0 : 0.6), { pen: 'ink.fine', single: true, bow: 0.003, opts: { simple: true, width: 0.95, alpha: 0.85 } })
}

export function swipeFill(ink: Ink, r: { x: number; y: number; w: number; h: number }, horizontal: boolean, calm: boolean): void {
  const along = horizontal ? r.w : r.h
  const inset = clamp(along * 0.02, 1, 4)
  const box = horizontal ? { x: r.x + inset, y: r.y, w: r.w - inset * 2, h: r.h } : { x: r.x, y: r.y + inset, w: r.w, h: r.h - inset * 2 }
  solidFill(ink, roundRectPoly(box.x, box.y, box.w, box.h, Math.min(5, Math.min(box.w, box.h) / 2)), 'hi', { alpha: calm ? 0.5 : 0.62, rough: 0.05 })
}

import type { Ink } from '@/lib/ink/builder'
import { blobFill, wash, type Offset } from '@/lib/ink/fills'
import { seg } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { focusRing, loop } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { arcPts, layoutGauge, layoutPie, layoutRadar, layoutRadial, polar, sectorPoly, TAU } from '@/lib/ink/charts/chart-polar'
import { slotKey, type GaugeSpec, type PieSpec, type RadarSpec, type RadialSpec } from '@/lib/ink/charts/chart-types'
import { hatchOn } from '@/lib/ink/recipes/chart-ink/xy'
import { drawMarker, patternFill } from '@/lib/ink/recipes/chart-ink/parts'
import type { Pt } from '@/lib/ink/types'

function ghostRing(ink: Ink, cx: number, cy: number, R: number, r0: number): void {
  ink.group(
    { part: 'pulse' },
    () => {
      ink.stroke(arcPts(cx, cy, R, 0.1, TAU + 0.16, 5), 'pencil', { simple: true, alpha: 0.7, width: 0.9, wobble: 0.8, poly: true })
      if (r0 > 4) ink.stroke(arcPts(cx, cy, r0, 0.4, TAU + 0.2, 5), 'pencil', { simple: true, alpha: 0.6, width: 0.9, wobble: 0.8, poly: true })
    },
    'top',
  )
}

export const pieRecipe = defineRecipe<PieSpec>({
  id: 'chart-pie',
  kind: 'chart',
  layers: ['rest', 'focus'],
  lazy: ['focus'],
  pad: 14,
  draw(ink, box, spec, ctx) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, box.w, box.h, { r: 6 }))
    if (ctx.lazyOnly) return
    const L = layoutPie(spec, box, ctx.calm)
    const { cx, cy, R, r0 } = L
    const calm = ctx.calm
    ink.layer('rest', () => {
      if (spec.state !== 'ready' || !L.sectors.length) {
        ghostRing(ink, cx, cy, R, r0)
        return
      }
      const many = L.sectors.length > 6
      const perSlice = clamp(Math.floor(160 / L.sectors.length), 10, 60)
      ink.group(
        { part: 'wipe' },
        () => {
          const gapA = Math.min(0.03, 1.4 / R)
          ink.part('fill', () => {
            let first: Offset | undefined
            for (const s of L.sectors) {
              const poly = sectorPoly(cx, cy, r0, R - 0.5, s.a0 + gapA, s.a1 - gapA, 5)
              const off = blobFill(ink, poly, slotKey(spec.slices[s.index].slot), { alpha: calm ? 0.8 : 0.88, mis: calm ? false : clamp(R * 0.02, 1, 2.6), rough: calm ? 0.3 : 0.6 })
              first ??= off
            }
            return first
          })
          for (const s of L.sectors) {
            const sl = spec.slices[s.index]
            if (spec.patterns && sl.pattern !== 'solid') patternFill(ink, sl.pattern, sectorPoly(cx, cy, r0 + 1.5, R - 2, s.a0 + gapA * 2, s.a1 - gapA * 2, 6), { color: hatchOn(sl.slot), maxPulls: perSlice, alpha: 0.7 })
          }
          const ring = { simple: many || calm, wobble: calm ? 0.2 : 0.7, poly: true as const }
          const one = L.sectors.length === 1
          const a = L.sectors[0]?.a0 ?? 0
          ink.stroke(arcPts(cx, cy, R, a, a + TAU + 0.07, 4), calm ? 'ink.fine' : 'ink', { ...ring, width: calm ? 0.9 : 0.95, end: 'flick' })
          if (r0 > 4) ink.stroke(arcPts(cx, cy, r0, a + 0.3, a + 0.3 + TAU + 0.06, 4), calm ? 'ink.fine' : 'ink.fine', { ...ring, width: 1.05, end: 'flick' })
          if (!one) {
            for (const s of L.sectors) {
              const p0 = polar(cx, cy, Math.max(0, r0 - 1.5), s.a0)
              const p1 = polar(cx, cy, R + 1.6, s.a0)
              ink.stroke(seg(p0[0], p0[1], p1[0], p1[1], 0.2, 3), calm ? 'ink.fine' : 'ink.fine', { simple: true, wobble: 0.3, width: 1.1, start: 'soft', end: 'flick' })
            }
          }
        },
        'top',
      )
    })
  },
})

export const radarRecipe = defineRecipe<RadarSpec>({
  id: 'chart-radar',
  kind: 'chart',
  layers: ['rest', 'focus'],
  lazy: ['focus'],
  pad: 14,
  draw(ink, box, spec, ctx) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, box.w, box.h, { r: 6 }))
    if (ctx.lazyOnly) return
    const L = layoutRadar(spec, box, ctx.calm)
    const { cx, cy, R } = L
    const calm = ctx.calm
    const n = spec.axes.length
    ink.layer('rest', () => {
      if (spec.state !== 'ready' || n < 3) {
        ghostRing(ink, cx, cy, R, 0)
        return
      }
      const rng = ink.next('web')
      L.rings.forEach((r, k) => {
        const ring = L.axesAngles.map((a) => polar(cx, cy, r, a))
        const alpha = k === L.rings.length - 1 ? 0.75 : 0.45
        ring.forEach((p, i) => {
          const q = ring[(i + 1) % ring.length]
          const len = Math.hypot(q[0] - p[0], q[1] - p[1]) || 1
          const over = calm ? 0 : rng.range(0.4, 1.6)
          const ux = (q[0] - p[0]) / len
          const uy = (q[1] - p[1]) / len
          ink.stroke(seg(p[0] - ux * over, p[1] - uy * over, q[0] + ux * over * 0.6, q[1] + uy * over * 0.6, calm ? 0 : rng.gauss(0, 0.004) * len, 4), 'pencil', { simple: true, alpha, width: calm ? 0.75 : 0.8, wobble: calm ? 0.2 : 0.6, start: 'soft', end: 'soft' })
        })
      })
      L.axesAngles.forEach((a) => {
        const p = polar(cx, cy, R, a)
        ink.stroke(seg(cx, cy, p[0], p[1], 0, 2), 'pencil', { simple: true, alpha: 0.5, width: 0.75, wobble: calm ? 0.2 : 0.6 })
      })
      ink.group(
        { part: 'wipe' },
        () => {
          spec.series.forEach((s, k) => {
            const key = slotKey(s.slot)
            const pts = L.polys[k].map((p, i) => p ?? polar(cx, cy, 0, L.axesAngles[i]))
            if (spec.fill) {
              wash(ink, pts, key, { alpha: calm ? 0.16 : 0.3, shift: calm ? 0 : 1.4, inset: 0.4, wobble: calm ? 0.2 : 0.5 })
              if (spec.patterns && s.pattern !== 'solid') patternFill(ink, s.pattern, pts, { color: key, maxPulls: 46, alpha: 0.55, gapK: 1.2 })
            }
            ink.stroke([...pts, pts[0], pts[1]], 'ink', { color: key, poly: true, round: 1.4, width: calm ? 1 : 1.15, wobble: 0.5, simple: calm || spec.series.length > 3, end: 'flick' })
            if (spec.dots) {
              pts.forEach((p, i) => {
                if (L.polys[k][i]) drawMarker(ink, spec.patterns ? s.marker : 'circle', p[0], p[1], 3.4, { color: key, rich: !calm && n * spec.series.length <= 40, pen: 'ink.fine' })
              })
            }
          })
        },
        'top',
      )
    })
  },
})

export const radialRecipe = defineRecipe<RadialSpec>({
  id: 'chart-radial',
  kind: 'chart',
  layers: ['rest', 'focus'],
  lazy: ['focus'],
  pad: 14,
  draw(ink, box, spec, ctx) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, box.w, box.h, { r: 6 }))
    if (ctx.lazyOnly) return
    const L = layoutRadial(spec, box, ctx.calm)
    const { cx, cy } = L
    const calm = ctx.calm
    ink.layer('rest', () => {
      if (spec.state !== 'ready' || !L.arcs.length) {
        ghostRing(ink, cx, cy, L.R, L.hole)
        return
      }
      for (const a of L.arcs) {
        const track = sectorPoly(cx, cy, a.r - a.t / 2, a.r + a.t / 2, a.a0, a.aEnd, 5)
        wash(ink, track, 'paper-shade', { alpha: 0.9, shift: 0, inset: 0.3, wobble: 0.3 })
        const rim = [...arcPts(cx, cy, a.r + a.t / 2, a.a0, a.aEnd, 5), ...arcPts(cx, cy, a.r - a.t / 2, a.aEnd, a.a0, 5)]
        ink.stroke([...rim, rim[0], rim[1]], 'pencil', { poly: true, round: 1.5, simple: true, alpha: 0.6, width: 0.75, wobble: 0.5 })
      }
      ink.group(
        { part: 'wipe' },
        () => {
          ink.part('fill', () => {
            let first: Offset | undefined
            for (const a of L.arcs) {
              if (a.a1 - a.a0 < 0.02) continue
              const poly = sectorPoly(cx, cy, a.r - a.t / 2 + 0.5, a.r + a.t / 2 - 0.5, a.a0, a.a1, 4)
              const off = blobFill(ink, poly, slotKey(spec.rings[a.index].slot), { alpha: calm ? 0.8 : 0.9, mis: calm ? false : 1.6, rough: 0.4 })
              first ??= off
            }
            return first
          })
          L.arcs.forEach((a) => {
            const ring = spec.rings[a.index]
            if (a.a1 - a.a0 < 0.02) return
            if (spec.patterns && ring.pattern !== 'solid') patternFill(ink, ring.pattern, sectorPoly(cx, cy, a.r - a.t / 2 + 1.5, a.r + a.t / 2 - 1.5, a.a0 + 0.02, a.a1 - 0.02, 5), { color: hatchOn(ring.slot), maxPulls: 34, alpha: 0.7 })
            const outline: Pt[] = [...arcPts(cx, cy, a.r + a.t / 2, a.a0, a.a1, 4), ...arcPts(cx, cy, a.r - a.t / 2, a.a1, a.a0, 4)]
            ink.stroke([...outline, outline[0], outline[1]], calm ? 'ink.fine' : 'ink.fine', { poly: true, simple: calm || L.arcs.length > 4, width: 1.05, wobble: 0.5, end: 'flick', round: 1.5 })
          })
        },
        'top',
      )
    })
  },
})

export const gaugeRecipe = defineRecipe<GaugeSpec>({
  id: 'chart-gauge',
  kind: 'chart',
  layers: ['rest', 'focus'],
  lazy: ['focus'],
  pad: 14,
  draw(ink, box, spec, ctx) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, box.w, box.h, { r: 6 }))
    if (ctx.lazyOnly) return
    const L = layoutGauge(spec, box, ctx.calm)
    const { cx, cy, R, t } = L
    const calm = ctx.calm
    ink.layer('rest', () => {
      if (spec.state !== 'ready') {
        ink.group({ part: 'pulse' }, () => ink.stroke(arcPts(cx, cy, R - t / 2, L.a0, L.a1, 5), 'pencil', { simple: true, alpha: 0.7, width: 0.9, wobble: 0.8, poly: true }), 'top')
        return
      }
      const zoned = L.zones.length > 0
      const track = sectorPoly(cx, cy, R - t, R, L.a0, L.a1, 4)
      if (!zoned) wash(ink, track, 'paper-shade', { alpha: 0.95, shift: calm ? 0 : 0.8, inset: 0.3, wobble: 0.3 })
      ink.group(
        { part: 'wipe' },
        () => {
          if (zoned) {
            ink.part('fill', () => {
              let first: Offset | undefined
              for (const z of L.zones) {
                const off = blobFill(ink, sectorPoly(cx, cy, R - t + 0.6, R - 0.6, z.a0, z.a1, 4), slotKey(z.slot), { alpha: calm ? 0.8 : 0.88, mis: calm ? false : 1.5, rough: 0.4 })
                first ??= off
              }
              return first
            })
            for (const z of L.zones) {
              if (spec.patterns && z.pattern !== 'solid') patternFill(ink, z.pattern, sectorPoly(cx, cy, R - t + 2, R - 2, z.a0 + 0.02, z.a1 - 0.02, 5), { color: hatchOn(z.slot), maxPulls: 30, alpha: 0.7 })
            }
          } else if (L.av - L.a0 > 0.02) {
            const key = slotKey(0)
            ink.part('fill', () => blobFill(ink, sectorPoly(cx, cy, R - t + 0.6, R - 0.6, L.a0, L.av, 4), key, { alpha: 0.9, mis: calm ? false : 1.5, rough: 0.4 }))
          }
          const pen = calm ? 'ink.fine' : 'ink'
          const open = { poly: true as const, wobble: calm ? 0.2 : 0.7, width: calm ? 0.9 : 1, end: 'flick' as const, simple: calm }
          ink.stroke(arcPts(cx, cy, R, L.a0 - 0.02, L.a1 + 0.03, 4), pen, open)
          ink.stroke(arcPts(cx, cy, R - t, L.a0 - 0.01, L.a1 + 0.02, 4), 'ink.fine', { ...open, width: 1.05 })
          for (const a of [L.a0, L.a1, ...L.zones.map((z) => z.a1)]) {
            const p0 = polar(cx, cy, R - t - 2, a)
            const p1 = polar(cx, cy, R + 2, a)
            ink.stroke(seg(p0[0], p0[1], p1[0], p1[1], 0.2, 3), 'ink.fine', { simple: true, wobble: 0.3, width: 1.05, start: 'soft', end: 'flick' })
          }
          if (!calm) {
            for (const a of L.tickAngles) {
              const p0 = polar(cx, cy, R + 4, a)
              const p1 = polar(cx, cy, R + 9, a)
              ink.stroke(seg(p0[0], p0[1], p1[0], p1[1], 0, 2), 'pencil', { simple: true, alpha: 0.6, width: 0.8, wobble: 0.3, end: 'flick' })
            }
          }
          if (zoned || spec.zones.length === 0) {
            const tip = polar(cx, cy, R - t * 0.2, L.av)
            const base = polar(cx, cy, 6, L.av + Math.PI)
            ink.stroke(seg(base[0], base[1], tip[0], tip[1], 0.7, 8), 'redfelt', { start: 'soft', end: 'flick', width: calm ? 1 : 1.3, wobble: 0.5, simple: calm })
            loop(ink, cx, cy, 5.4, 5.2, { pen: 'ink.fine', opts: { simple: true, width: 1 } })
            ink.dot(cx, cy, 2.4, 'ink')
          }
        },
        'top',
      )
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import { blobFill, flatFill } from '@/lib/ink/fills'
import { ellipsePoly, seg } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { arrow, dashedBox, focusRing, loop, squiggle, underline } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { layoutXY, type XYBar, type XYLayout } from '@/lib/ink/charts/chart-xy'
import { slotKey, type XYSpec } from '@/lib/ink/charts/chart-types'
import { NOTE_PEN, drawAxisLines, drawGrid, drawMarker, drawPolyline, patternFill, rectPts, swipeFill } from '@/lib/ink/recipes/chart-ink/parts'
import type { PaintKey } from '@/lib/ink/paint'
import type { PenName, Pt } from '@/lib/ink/types'

export const HATCH_ON: readonly PaintKey[] = ['ink', 'photo', 'photo', 'photo', 'photo', 'photo', 'photo', 'photo']
export const hatchOn = (slot: number): PaintKey => HATCH_ON[((Math.trunc(slot) % 8) + 8) % 8]

function barShape(b: XYBar, horizontal: boolean): Pt[] {
  const r = Math.min(3, Math.min(b.w, b.h) * 0.35)
  const steps = 5
  const arc = (cx: number, cy: number, a0: number): Pt[] => Array.from({ length: steps + 1 }, (_, i) => {
    const a = a0 + (i / steps) * (Math.PI / 2)
    return [cx + Math.cos(a) * r, cy + Math.sin(a) * r] as Pt
  })
  const { x, y, w, h } = b
  if (horizontal) {
    if (b.neg) return [[x + w, y], ...arc(x + r, y + r, Math.PI * 1.5).reverse(), ...arc(x + r, y + h - r, Math.PI * 0.5).reverse(), [x + w, y + h]]
    return [[x, y], ...arc(x + w - r, y + r, Math.PI * 1.5), ...arc(x + w - r, y + h - r, 0), [x, y + h]]
  }
  if (b.neg) return [[x, y], [x + w, y], ...arc(x + w - r, y + h - r, 0), ...arc(x + r, y + h - r, Math.PI * 0.5)]
  return [[x, y + h], ...arc(x + r, y + r, Math.PI), ...arc(x + w - r, y + r, Math.PI * 1.5), [x + w, y + h]]
}

function drawBarFills(ink: Ink, bars: readonly XYBar[], spec: XYSpec, calm: boolean, horizontal: boolean): void {
  if (!bars.some((b) => b.w >= 0.8 && b.h >= 0.8)) return
  ink.part('fill', () => {
    let first: { dx: number; dy: number } | undefined
    for (const b of bars) {
      if (b.w < 0.8 || b.h < 0.8) continue
      flatFill(ink, barShape(b, horizontal), slotKey(spec.series[b.s].slot), calm ? 0.88 : 0.95)
      first ??= { dx: 0, dy: 0 }
    }
    return first
  })
}

function drawBar(ink: Ink, b: XYBar, L: XYLayout, spec: XYSpec, o: { rich: boolean; calm: boolean; maxPulls: number; pen: PenName }): void {
  const ser = spec.series[b.s]
  if (b.w < 0.8 || b.h < 0.8) return
  const short = Math.min(b.w, b.h)
  const rng = ink.next('bar')
  if (spec.patterns && ser.pattern !== 'solid' && b.w >= 8 && b.h >= 8) {
    patternFill(ink, ser.pattern, rectPts(b.x + 1.2, b.y + 1.2, b.w - 2.4, b.h - 2.2), { color: hatchOn(ser.slot), maxPulls: o.maxPulls, alpha: 0.72 })
  }
  if (b.w < 6 && !L.horizontal) return
  const j = () => rng.gauss(0, 0.12)
  const { x, y, w, h } = b
  let pts: Pt[]
  if (L.horizontal) pts = b.neg ? [[x + w, y + j()], [x + j(), y + j()], [x + j(), y + h + j()], [x + w, y + h + j()]] : [[x, y + j()], [x + w + j(), y + j()], [x + w + j(), y + h + j()], [x, y + h + j()]]
  else pts = b.neg ? [[x + j(), y], [x + j(), y + h + j()], [x + w + j(), y + h + j()], [x + w + j(), y]] : [[x + j(), y + h], [x + j(), y + j()], [x + w + j(), y + j()], [x + w + j(), y + h]]
  ink.stroke(pts, o.pen, { poly: true, round: Math.min(3, short * 0.35), simple: !o.rich, wobble: 0.15, dry: 0, end: 'soft', start: 'soft' })
}

function drawNotes(ink: Ink, L: XYLayout, spec: XYSpec): void {
  ink.group(
    { part: 'note' },
    () => {
      for (const g of L.notes) {
        const p = NOTE_PEN[g.pen]
        if (g.loop) loop(ink, g.loop.cx, g.loop.cy, g.loop.rx, g.loop.ry, { pen: p.std, opts: { width: 0.9 } })
        if (g.underline) underline(ink, g.underline.x1, g.underline.y, g.underline.x2 - g.underline.x1, { pen: p.fine, kind: 'double' })
        if (g.arrow) arrow(ink, g.arrow.x1, g.arrow.y1, g.arrow.x2, g.arrow.y2, { pen: p.fine, curve: 0.22, headLen: 7, opts: { width: 1.05 } })
      }
      for (const r of L.refs) {
        const len = Math.hypot(r.x2 - r.x1, r.y2 - r.y1)
        const p = NOTE_PEN[r.pen]
        const rng = ink.next('ref')
        for (let d = 0; d < len; d += 15 + rng.range(-1, 1)) {
          const a = d / len
          const e = Math.min(len, d + 9) / len
          ink.stroke(seg(r.x1 + (r.x2 - r.x1) * a, r.y1 + (r.y2 - r.y1) * a, r.x1 + (r.x2 - r.x1) * e, r.y1 + (r.y2 - r.y1) * e + rng.gauss(0, 0.3), 0.1, 2), p.fine === 'redfelt.fine' ? 'red' : 'pencil', { simple: true, alpha: 0.85, width: 0.95, start: 'soft', end: 'soft' })
        }
      }
    },
    'top',
  )
  void spec
}

function drawTicks(ink: Ink, L: XYLayout, calm: boolean): void {
  const { x0, x1, y1 } = L.plot
  const along = (l: { x: number; y: number }, bottom: boolean) => {
    const rng = ink.next('tick')
    const j = rng.gauss(0, 0.25)
    if (bottom) ink.stroke([[l.x + j, y1 - 1.2], [l.x + rng.gauss(0, 0.2), y1 + (calm ? 3.5 : 4.6)]], calm ? 'ink.fine' : 'ink.fine', { simple: true, width: 0.9, alpha: 0.85, start: 'soft', end: 'flick', wobble: 0.3 })
    else ink.stroke([[x0 + 1.2, l.y + j], [x0 - (calm ? 3.5 : 4.6), l.y + rng.gauss(0, 0.2)]], 'pencil', { simple: true, width: 0.95, alpha: 0.85, start: 'soft', end: 'flick', wobble: 0.3 })
  }
  for (const l of L.labels) {
    if (l.x < x0 - 60 || l.x > x1 + 60) continue
    if (L.horizontal) {
      if (l.role === 'y') along(l, true)
      else if (l.role === 'cat') along(l, false)
    } else if (l.role === 'x') along(l, true)
    else if (l.role === 'y') along(l, false)
  }
}

function drawState(ink: Ink, L: XYLayout, spec: XYSpec, calm: boolean): void {
  const { x0, y0, x1, y1 } = L.plot
  drawAxisLines(ink, L.plot, { x: true, y: true, calm })
  if (spec.state === 'loading') {
    ink.group(
      { part: 'pulse' },
      () => {
        const hs = [0.26, 0.42, 0.32, 0.52, 0.38, 0.46]
        const bw = Math.min(46, (x1 - x0) / (hs.length * 1.7))
        const step = (x1 - x0) / hs.length
        hs.forEach((k, i) => {
          const hh = (y1 - y0) * k
          dashedBox(ink, x0 + step * (i + 0.5) - bw / 2, y1 - hh, bw, hh, { r: 2, pen: 'pencil', opts: { alpha: 0.7 } })
        })
      },
      'top',
    )
  } else {
    squiggle(ink, x0 + 12, y0 + (y1 - y0) * 0.68, Math.max(20, x1 - x0 - 24), { pen: 'pencil', h: 14, amp: 1.4, wl: 1.3, opts: { alpha: 0.55 } })
  }
}

export const xyRecipe = defineRecipe<XYSpec>({
  id: 'chart-xy',
  kind: 'chart',
  layers: ['rest', 'focus'],
  lazy: ['focus'],
  pad: 14,
  draw(ink, box, spec, ctx) {
    ctx.lazy('focus', (f) => focusRing(f, 0, 0, box.w, box.h, { r: 6 }))
    if (ctx.lazyOnly) return
    const calm = ctx.calm
    const L = layoutXY(spec, box, calm)
    const { plot } = L
    ink.layer('rest', () => {
      if (spec.state !== 'ready' || spec.series.length === 0 || spec.cats.length + L.dots.length === 0) {
        drawState(ink, L, spec, calm)
        return
      }
      for (const b of L.bands) swipeFill(ink, b, L.horizontal, calm)
      if (spec.grid) drawGrid(ink, L.gridPx, plot, !L.horizontal, calm)
      drawAxisLines(ink, plot, { x: true, y: spec.showY, calm, zeroY: L.horizontal ? null : L.basePx })
      drawTicks(ink, L, calm)

      const rich = !calm && L.bars.length <= 18 && L.dots.length <= 60
      const patterned = L.bars.filter((b) => spec.series[b.s].pattern !== 'solid' && b.w >= 8).length
      const maxPulls = clamp(Math.floor(150 / Math.max(1, patterned)), 9, 60)
      const barPen: PenName = calm ? 'ink.fine' : L.barW >= 24 ? 'ink' : 'ink.fine'

      ink.group(
        { part: 'wipe' },
        () => {
          for (const a of L.areas) {
            const ser = spec.series[a.s]
            const key = slotKey(ser.slot)
            for (const poly of a.polys) {
              flatFill(ink, poly, key, 0.42)
            }
          }
          drawBarFills(ink, L.bars, spec, calm, L.horizontal)
          for (const b of L.bars) drawBar(ink, b, L, spec, { rich, calm, maxPulls, pen: barPen })
          const heavy = L.lines.reduce((n, l) => n + l.segs.reduce((m, s) => m + s.length, 0), 0) > 170
          for (const l of L.lines) {
            const ser = spec.series[l.s]
            const key = slotKey(ser.slot)
            for (const s of l.segs) {
              if (s.length < 2) {
                if (s.length === 1) ink.dot(s[0][0], s[0][1], 2, 'ink', { color: key })
                continue
              }
              drawPolyline(ink, s, spec.patterns && ser.kind === 'line' ? ser.dash : 'solid', calm ? 'ink.fine' : 'ink', { color: key, width: calm ? 1.05 : 1.2, simple: heavy })
            }
          }
          const lean = !rich || L.dots.length > 40
          for (const d of L.dots) {
            const ser = spec.series[d.s]
            const key = slotKey(ser.slot)
            const scatter = ser.kind === 'scatter'
            const sized = scatter && !!ser.sizes
            if (sized) {
              blobFill(ink, ellipsePoly(d.x, d.y, d.r, d.r, 14), key, { alpha: 0.5, mis: calm ? false : 1.1 })
              if (!lean) loop(ink, d.x, d.y, d.r, d.r, { pen: 'ink.fine', opts: { simple: true, width: 1 } })
              continue
            }
            const shape = spec.patterns || !scatter ? ser.marker : 'circle'
            if (scatter && shape === 'circle' && !lean) blobFill(ink, ellipsePoly(d.x, d.y, d.r * 0.8, d.r * 0.8, 12), key, { alpha: calm ? 0.3 : 0.4, mis: calm ? false : 0.8, rough: 0.3 })
            drawMarker(ink, shape, d.x, d.y, scatter ? Math.max(3.2, d.r * 0.78) : d.r, { color: key, rich: !lean && !calm, pen: 'ink.fine', width: scatter ? 1.4 : undefined })
          }
        },
        'top',
      )
      if (L.notes.length || L.refs.length) drawNotes(ink, L, spec)
    })
  },
})

